function card(p,i=0){const status=p.price?(p.mode==='Unavailable'?'unavailable':'orderable'):'inspiration';return `<article class="product" data-status="${status}"><a href="cake.html?id=${p.id}"><div class="product-photo"><span class="product-index" aria-hidden="true">${String(i+1).padStart(2,'0')}</span>${image(p.id,'',true)}<span class="product-view" aria-hidden="true">View cake <span class="arrow">→</span></span></div><div class="product-text"><h2>${p.name}</h2><p class="price">${p.price?(p.sizes?'From '+money(p.price):money(p.price)):'By request'}</p></div><p class="meta">${cardMeta(p)}</p></a><button class="save" data-save="${p.id}" aria-label="${saved().includes(p.id)?'Unsave':'Save'} ${p.name}" aria-pressed="${saved().includes(p.id)}">${icon('heart')}</button></article>`}

// Cake page: buy this cake, request changes to this exact photo, or (r02) reorder.
function archivedPage(){return `<div class="wrap">${title('This cake is no longer in our collection','It may have been retired or replaced by the chef.')}<div class="narrow"><div class="notice">This design has been archived, so it can’t be ordered or opened here any more. Orders you’ve already placed are not affected.</div><p>Loved it? Tell us what you liked and the chef will help you create something similar.</p><div class="form-actions"><a class="button primary" href="custom.html?ref=none">Start a custom request →</a><a class="button" href="shop.html">Browse current cakes</a></div><p class="small quiet">If you ordered this cake before, you’ll be able to sign in and request something similar from that order, with the photo from your order (account pages come in the next sketch).</p></div></div>`}
function detail(){
 const p=product(params.get('id'));if(!p)return `<div class="wrap">${empty('Cake not found','Explore the collection to choose another cake.')}</div>`;
 if(DEMO==='archived')return archivedPage();
 // K01: a cake without an approved allergen disclosure can't be bought, but you can still ask about it (demo "no-allergens").
 const noDisclosure=DEMO==='no-allergens'&&!!p.price,ready=p.stock==='ready',tooLate=ready&&!!chosenDate()&&chosenDate()>READY_UNTIL,orderable=!!p.price&&p.mode!=='Unavailable'&&!noDisclosure,rev=currentRev(p.id),base=product(imgOf(p)),list=noDisclosure?[]:containsList(p);
 const tag=!p.price?'Inspiration · by request':p.mode==='Unavailable'?'Not available right now':ready?`Ready-made · ${p.readyLeft} left · collect by ${shortDate(READY_UNTIL)}`:'Made to order';
 const sizeBlock=base.sizes?`<fieldset class="field size-choice"><legend>Size</legend><div class="size-options">${base.sizes.map(id=>{const v=product(id);return `<label class="choice-chip"><input type="radio" name="size" value="${id}" ${id===p.id?'checked':''}><span>${v.size.split(' · ')[0]} · ${v.size.split(' · ')[1].replace(' inches',' in')} · ${v.serves} · ${money(v.price)}</span></label>`}).join('')}</div><p class="small quiet">Sizes chosen by the chef for this cake (example). <a href="sizes.html">Sizes and starting prices</a></p></fieldset>`:'';
 const dateNote=!p.price?'':noDisclosure?'<div class="notice error" id="cake-date-status">Allergen information for this cake is still being checked, so it can’t be bought yet. You can still ask the chef about it or request your own version.</div>':tooLate?`<div class="notice error" id="cake-date-status">Your date, ${escape(dateLabel(chosenDate()))}, is after this ready-made cake’s collect-by date (${escape(shortDate(READY_UNTIL))}). Please choose an earlier date.</div>`:p.mode==='Unavailable'?'<div class="notice error" id="cake-date-status">This cake can’t be ordered right now. You can request your own version of it, or save it and come back later.</div>':`<div class="notice" id="cake-date-status">${chosenDate()?`Your date: ${escape(dateLabel(chosenDate()))}${read('slot','')?' · '+escape(read('slot','')):''}. Nothing is reserved until you pay.`:'Choose a date and time to add this cake. Nothing is reserved until you pay.'}</div>`;
 const changed=DEMO==='image-changed'&&rev>base.rev?`<div class="notice" role="note">The chef updated this photo. New requests use the photo shown here (version ${rev}); a request you have already started keeps the photo you chose.</div>`:'';
 return `<div class="wrap"><div class="breadcrumb"><a href="shop.html">Shop cakes</a> &nbsp; / &nbsp; ${p.name}</div><section class="detail"><div class="detail-visual">${image(p.id,revClass(p.id,rev),true)}</div><div class="detail-copy"><span class="tag">${tag}</span><h1>${p.name}</h1><p class="flavour">${p.flavour||'A starting point for your own creation'}</p>${changed}<p class="detail-price">${p.price?money(p.price):'Price agreed with the chef'}</p>
 ${hasPeanuts(p)?'<div class="peanut-alert" role="note"><strong>Contains PEANUTS</strong><span>This Snickers cake has peanut cream cheese cream, peanuts and caramel. Please check before ordering.</span></div>':''}
 ${p.price?`${sizeBlock}<div class="facts"><span>${p.size}</span><span>${p.serves} servings</span><span>${p.weight}</span></div><p class="description">${p.composition}</p>${noDisclosure?'<p class="contains"><strong>Allergen information is not available yet.</strong></p>':`<p class="contains"><strong>Contains: ${list.join(', ')}.</strong> <a href="#allergens">Full allergen notice</a></p>`}<p class="small quiet">Finished with Swiss meringue buttercream. The decoration shown is included. Changes and extras need a price agreed with the chef before you pay.</p>${ready?`<div class="notice" role="note">Ready-made example: this cake is already made, so it doesn’t use one of the day’s places. It must be collected by ${escape(longDate(READY_UNTIL))}: the chef’s collect-by date for this cake (example date; the chef sets it for each ready-made cake). The usual 192-hour notice applies unless the chef has approved shorter notice for this cake.</div>`:''}`:`<p class="description">Love this design? Use it as the starting point for a cake made for you. Share your date, servings and flavour, then agree the details and price with Elina.</p><p class="small quiet">This gallery photo has no set flavour, size or price, so it can’t be bought directly. <a href="sizes.html">Sizes and starting prices</a></p>`}
 ${dateNote}<div class="action-stack">${orderable?`<button data-date>${icon('calendar')} ${chosenDate()?'Change date or time':'Choose your date and time'}</button><button class="primary" id="add-bag" data-product="${p.id}" ${chosenDate()&&!tooLate?'':'disabled'}>Add to bag · ${money(p.price)} ${icon('arrow')}</button>`:noDisclosure?'<button disabled>Can’t be bought yet</button>':p.mode==='Unavailable'?'<button disabled>Not available right now</button>':''}<a class="button ${!p.price?'primary':''}" href="custom.html?ref=${imgOf(p)}&amp;rev=${rev}${DEMO==='image-changed'?'&amp;demo=image-changed':''}" id="request-changes">${p.price?'Request changes to this design':'Request this design'} ${icon('arrow')}</a><p class="small quiet pin-note">Your request will include this exact photo (photo version ${rev}).</p></div><p class="small quiet">Collect for free at St Katharine Docks, send your own courier, or ask for GK delivery (quoted by the chef from £100 and paid separately).</p>${p.price?`<details class="accordion" id="allergens" open><summary>Ingredients & allergens</summary><p>${p.composition} Standard coating: Swiss meringue buttercream.</p>${hasPeanuts(p)?'<p class="allergen-alert">Contains PEANUTS</p>':''}${noDisclosure?'<p><strong>Allergen information is not available yet, so this cake can’t be bought.</strong></p>':`<p><strong>Contains: ${list.join(', ')}.</strong></p>`}<p class="cross-contact">${NOTICE}</p><p class="small quiet">Final product, decoration and supplier-label checks are still needed before launch.</p></details>`:''}<details class="accordion"><summary>Sizes & changes</summary><p>${base.sizes?'This cake comes in the sizes above.':p.price?'This cake comes in the size shown.':'Size and design details are agreed with the chef.'} For another size, colour or flavour, choose “Request changes to this design”. See <a href="sizes.html">sizes and starting prices</a>.</p></details><details class="accordion"><summary>Collection & your date</summary><p>Collection is from St Katharine Docks, London, Thursday to Sunday. Cakes need at least 192 hours’ notice from payment to handover. Dates open up to about two months ahead.</p><a href="faq.html#collection">Collection and delivery details →</a></details></div></section></div>${banner()}`}

// Shared date-and-time picker: one calendar, one Collect / Own courier / GK delivery switch, one slot list.
function modeSwitch(name,current){return `<fieldset class="co-modes picker-modes"><legend class="picker-legend">How you’ll get your cake</legend>${[['collection','Collect · Free','St Katharine Docks, London.'],['courier','Own courier','You book and pay a courier to collect from us.'],['delivery','GK delivery · from £100','Times are requested; the chef confirms and quotes.']].map(([v,t,s])=>`<label class="mode-card"><input type="radio" name="${name}" value="${v}" ${current===v?'checked':''}><span><strong>${t}</strong><small>${s}</small></span></label>`).join('')}</fieldset>`}
function slotField(id,legend){return `<fieldset class="slot-field" id="${id}" tabindex="-1" aria-describedby="${id}-status"><legend id="${id}-legend">${legend}</legend><p class="slot-status" id="${id}-status" role="status"></p><div class="slot-list" id="${id}-list"></div><div class="slot-extra" id="${id}-extra"></div></fieldset>`}
function calendar(target,value,purpose='purchase',hidden=false,qty=1,until=''){const note=purpose==='request'?`Thursday to Sunday, up to 8 months ahead. <span aria-hidden="true">✱</span> Under 8 days’ notice, or more than 2 months ahead for a cake that isn’t a wedding cake: you can still ask, and the chef will confirm.`:`Open Thursday to Sunday. Numbers show places left that day. Bookable from 192 hours ahead until ${shortDate(HORIZON)} (example last date; the chef sets it).${until?` Your ready-made cake must be collected by ${shortDate(until)}, the chef’s collect-by date.`:''}`;return `<div class="calendar picker-cal" data-calendar data-target="${target}" data-purpose="${purpose}" data-qty="${qty}" data-until="${until}" data-wedding="false" ${hidden?'hidden':''}><div class="calendar-heading"><button type="button" data-month="-1" aria-label="Previous month">‹</button><h3 aria-live="polite"></h3><button type="button" data-month="1" aria-label="Next month">›</button></div><div class="weekdays" aria-hidden="true">${['M','T','W','T','F','S','S'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-days" role="group" aria-label="Choose a day"></div><p class="calendar-note">${note}</p></div>`}
function dateDialog(){const extra=PAGE==='cake'?params.get('id'):null,q=placesNeeded(extra),until=readyUntil(extra);const m=read('mode','collection');return `<dialog id="date-dialog" class="picker-dialog" aria-labelledby="date-title"><form method="dialog"><button class="icon-button picker-close" aria-label="Close date and time picker">×</button></form><h2 class="form-heading" id="date-title">Choose your date and time</h2><p class="small quiet">London time. Example availability for design review; nothing is reserved until you pay.</p>${modeSwitch('picker-mode',['collection','courier','delivery'].includes(m)?m:'collection')}<input id="date-input" type="hidden" value="${chosenDate()}">${calendar('date-input',chosenDate(),'purchase',false,q,until)}<div id="taken-alert" class="notice error" role="alert" tabindex="-1" hidden></div>${slotField('date-slots','Times · London time')}<button id="date-use" class="primary" type="button" disabled>Choose a date and time</button><p class="small quiet">${EXAMPLE_TIMES_NOTE}</p></dialog>`}
function bindCalendars(){document.querySelectorAll('[data-calendar]').forEach(panel=>{
 const input=document.getElementById(panel.dataset.target),trigger=document.querySelector(`[data-calendar-toggle="${input.id}"]`),purpose=panel.dataset.purpose;
 const info=d=>dayInfo(d,purpose,purpose==='purchase'?Number(panel.dataset.qty||1):0,{until:panel.dataset.until||'',wedding:panel.dataset.wedding==='true'});
 const first=()=>{for(let i=0;i<260;i++){const d=addDays(TODAY,i);if(info(d).enabled)return d}return TODAY};
 const last=purpose==='request'?REQUEST_MAX:HORIZON;
 let shown=(input.value||first()).slice(0,8)+'01';
 function paint(focusDay){
  const [y,m]=shown.split('-').map(Number),offset=(weekday(shown)+6)%7,count=new Date(Date.UTC(y,m,0)).getUTCDate();
  panel.querySelector('h3').textContent=new Date(shown+'T12:00:00Z').toLocaleDateString('en-GB',{month:'long',year:'numeric',timeZone:'UTC'});
  const dates=Array.from({length:count},(_,i)=>addDays(shown,i));
  const focus=[focusDay,input.value,...dates].find(d=>d&&dates.includes(d)&&info(d).enabled);
  panel.querySelector('.calendar-days').innerHTML='<span></span>'.repeat(offset)+dates.map((d,i)=>{const f=info(d);const tag=f.confirm?'<small aria-hidden="true">✱</small>':f.label?`<small>${f.label}</small>`:'';return `<button type="button" data-day="${d}" class="day s-${f.status}" ${f.enabled?'':'disabled'} aria-label="${dateLabel(d)}${ariaFor(f)}" aria-pressed="${input.value===d}" tabindex="${d===focus?0:-1}"><span>${i+1}</span>${tag}</button>`}).join('');
  panel.querySelector('[data-month="-1"]').disabled=shown<=TODAY.slice(0,8)+'01';
  panel.querySelector('[data-month="1"]').disabled=shown>=last.slice(0,8)+'01';
  if(focusDay)(panel.querySelector(`[data-day="${focus}"]`)||panel.querySelector('[data-month]:not(:disabled)')).focus();
 }
 function close(){if(trigger){panel.hidden=true;trigger.setAttribute('aria-expanded','false');trigger.focus()}}
 panel.repaint=()=>paint();
 panel.select=d=>{input.value=d;shown=d.slice(0,8)+'01';paint(d);input.dispatchEvent(new Event('input',{bubbles:true}));if(trigger)trigger.querySelector('.date-value').textContent=dateLabel(d)};
 trigger?.addEventListener('click',()=>{panel.hidden=!panel.hidden;trigger.setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden)(panel.querySelector('[data-day][tabindex="0"]')||panel.querySelector('[data-month]:not(:disabled)')).focus()});
 panel.querySelectorAll('[data-month]').forEach(b=>b.addEventListener('click',()=>{const [y,m]=shown.split('-').map(Number);shown=new Date(Date.UTC(y,m-1+Number(b.dataset.month),1,12)).toISOString().slice(0,10);paint()}));
 panel.addEventListener('click',e=>{const b=e.target.closest('[data-day]');if(!b||b.disabled)return;input.value=b.dataset.day;input.dispatchEvent(new Event('input',{bubbles:true}));if(trigger){trigger.querySelector('.date-value').textContent=dateLabel(input.value);trigger.removeAttribute('aria-invalid');const err=document.querySelector('#request-date-error');if(err)err.hidden=true}paint(input.value);close()});
 panel.addEventListener('keydown',e=>{
  if(e.key==='Escape'&&trigger){e.preventDefault();e.stopPropagation();close();return}
  const b=e.target.closest('[data-day]');if(!b)return;
  let d=b.dataset.day,dir=1;const delta={ArrowLeft:-1,ArrowRight:1,ArrowUp:-7,ArrowDown:7}[e.key];
  if(delta!==undefined){d=addDays(d,delta);dir=Math.sign(delta)}else if(e.key==='PageUp'||e.key==='PageDown'){dir=e.key==='PageUp'?-1:1;d=addMonths(d,dir)}else return;
  e.preventDefault();let guard=0;while(!info(d).enabled&&guard++<70)d=addDays(d,dir);if(!info(d).enabled)return;
  shown=d.slice(0,8)+'01';paint(d);
 });paint();
})}
// Simulated schedule fetch: loading, list, empty and error are distinct; obsolete responses are discarded.
function slotPicker({id,name,purpose,date,mode,qty,selected,onChange,onPickDate,opts=()=>({})}){
 const root=document.getElementById(id),list=root.querySelector('.slot-list'),status=root.querySelector('.slot-status'),extra=root.querySelector('.slot-extra');
 let revision=0,failOnce=DEMO==='times-error',lastValue='';
 async function refresh(){
  const rev=++revision,d=date(),m=mode(),q=qty(),wanted=selected();extra.innerHTML='';
  if(!d){list.innerHTML='';status.textContent=purpose==='request'?'Choose a date to see example times.':'Choose a date to see its times.';lastValue='';onChange?.('');return}
  list.innerHTML='<span class="slot-skeleton" aria-hidden="true"></span>'.repeat(4);root.setAttribute('aria-busy','true');
  status.textContent=`Loading times for ${shortDate(d)}…`;onChange?.(null);
  await wait(DEMO==='times-slow'?3500:450);
  if(rev!==revision)return;
  root.removeAttribute('aria-busy');
  if(failOnce){failOnce=false;list.innerHTML='';status.textContent=`We couldn’t load the times for ${shortDate(d)}. Your other choices are kept.`;extra.innerHTML='<button type="button" class="retry">Try again</button>';extra.querySelector('.retry').addEventListener('click',()=>refresh());onChange?.('','error');return}
  // Demo "no times": only the first date asked for is empty; the suggested dates still have times.
  if(DEMO==='times-empty'&&!read('empty-date',''))write('empty-date',d);
  const o=opts(),res=DEMO==='times-empty'&&read('empty-date','')===d?{slots:[],reason:'no_times'}:scheduleFor(d,m,purpose,q,o);
  if(!res.slots.length){list.innerHTML='';status.textContent=({full:`${shortDate(d)} is now full.`,lead_time:`${shortDate(d)} is now less than 192 hours away.`,ready_expiry:`${shortDate(d)} is after your ready-made cake’s collect-by date.`}[res.reason]||`No times left on ${shortDate(d)}.`)+' Choose another date, or contact the chef.';const alt=nextOpenDates(d,2,purpose,q,o).filter(a=>a!==read('empty-date',''));extra.innerHTML=`<div class="slot-empty">${alt.map(a=>`<button type="button" data-alt-date="${a}">Try ${shortDate(a)}</button>`).join('')}<a class="text-link" href="contact.html">Contact the chef →</a></div>`;extra.querySelectorAll('[data-alt-date]').forEach(b=>b.addEventListener('click',()=>onPickDate?.(b.dataset.altDate)));lastValue='';onChange?.('');return}
  const keep=res.slots.some(s=>s.label===wanted)?wanted:'';
  list.innerHTML=res.slots.map(s=>`<label class="slot-option"><input type="radio" name="${name}" value="${s.label}" data-slot-id="${s.id}" ${s.label===keep?'checked':''}><span><strong>${s.label}</strong><small>${s.availability==='requestable'?(m==='delivery'?'Requested, the chef confirms':'Preferred, the chef confirms'):'Available'}</small></span></label>`).join('');
  const intro=purpose==='request'?`Example times for ${new Date(d+'T12:00:00Z').toLocaleDateString('en-GB',{weekday:'long',timeZone:'UTC'})}. Choosing one is optional; the chef confirms your time.`:`${res.slots.length} ${res.slots.length===1?'time':'times'} on ${shortDate(d)}.${m==='delivery'?' Delivery times are requested; the chef confirms.':''}`;
  status.textContent=`${intro} ${keep?`Your time ${keep} is still free.`:wanted?`${wanted} isn’t available for this choice, so please pick another.`:''}${res.hiddenLead?' Earlier times that day are less than 192 hours away.':''}`.trim();
  lastValue=keep;onChange?.(keep,'list');
 }
 root.addEventListener('change',e=>{if(e.target.name===name){lastValue=e.target.value;onChange?.(lastValue,'pick')}});
 return{refresh,get value(){return root.querySelector(`input[name="${name}"]:checked`)?.value||''}};
}
function bindPicker(){
 const dialog=document.querySelector('#date-dialog');if(!dialog)return;
 const input=dialog.querySelector('#date-input'),use=dialog.querySelector('#date-use'),alert=dialog.querySelector('#taken-alert'),cal=dialog.querySelector('[data-calendar]');
 const mode=()=>dialog.querySelector('[name=picker-mode]:checked')?.value||'collection';
 let wanted=read('slot',''),busy=false,modeTouched=false;
 const setMode=v=>{const r=dialog.querySelector(`[name=picker-mode][value="${v}"]`);if(r)r.checked=true};
 function setUse(v){if(v===null){use.disabled=true;use.textContent='Loading times…';return}use.disabled=!v||!input.value;use.textContent=v?`Use ${shortDate(input.value)} · ${v}${mode()==='delivery'?' (requested)':''}`:input.value?'Choose a time':'Choose a date and time'}
 const picker=slotPicker({id:'date-slots',name:'picker-slot',purpose:'purchase',date:()=>input.value,mode,qty:()=>Number(cal.dataset.qty),opts:()=>({until:cal.dataset.until||''}),selected:()=>wanted,onChange:v=>{if(v)wanted=v;setUse(v)},onPickDate:d=>cal.select(d)});
 // Opened from checkout, the picker starts from checkout's current handover choice (never silently resets it).
 document.querySelectorAll('[data-date]').forEach(b=>b.addEventListener('click',()=>{const co=document.querySelector('#checkout-form [name=fulfilment]:checked');if(co){setMode(co.value);modeTouched=false}dialog.showModal();(dialog.querySelector('[data-day][tabindex="0"]')||dialog.querySelector('[data-month]:not(:disabled)')).focus();picker.refresh()}));
 input.addEventListener('input',()=>{alert.hidden=true;picker.refresh()});
 dialog.querySelectorAll('[name=picker-mode]').forEach(r=>r.addEventListener('change',()=>{modeTouched=true;picker.refresh()}));
 use.addEventListener('click',async()=>{
  const d=input.value,slot=picker.value,m=mode();if(!d||!slot||busy)return;
  busy=true;use.disabled=true;use.textContent='Checking your time…';await wait(450);busy=false;
  if(DEMO==='time-taken'&&!read('taken-done',false)){write('taken-done',true);const full=read('full-days',[]);full.push(d);write('full-days',full);takenDays.add(d);wanted='';alert.hidden=false;alert.innerHTML=`<p><strong>Sorry, ${shortDate(d)} has just filled up.</strong> Someone took the last place while you were choosing. Your cake and how you’ll get it are kept. Please choose another date; we haven’t picked one for you.</p>`;cal.repaint();alert.focus();picker.refresh();return}
  if(DEMO==='time-too-soon'&&!read('soon-done',false)){write('soon-done',true);write('too-soon',[`${d}T${slot.slice(0,5)}`]);wanted='';alert.hidden=false;alert.innerHTML=`<p><strong>${slot} on ${shortDate(d)} is now less than 192 hours away</strong>, so it can’t be booked. Here are the times still open. Your date and other choices are kept.</p>`;alert.focus();picker.refresh();return}
  if(!write('date',d)||!write('slot',slot))return;if(modeTouched)write('mode',m);
  // Checkout keeps everything typed: update date, time and (only if changed here) the handover choice in place.
  if(PAGE==='checkout'){dialog.close();document.dispatchEvent(new CustomEvent('gk:when-changed',{detail:{date:d,slot,mode:modeTouched?m:null}}));return}
  dialog.close();location.reload()
 });
 setUse('');
}
function home(){const pick=product('pink'),notes=['Handcrafted in London','Swiss meringue buttercream','Bespoke designs on request','Collection at St Katharine Docks','GK delivery quoted individually'],tick=notes.map(n=>`<span>${n}</span><i aria-hidden="true">✦</i>`).join('');return `<section class="hero"><div class="wrap hero-inner"><div class="hero-copy"><p class="eyebrow kicker"><i class="dot" aria-hidden="true"></i>Handcrafted cakes · London</p><h1>Cakes that make moments <em>unforgettable</em></h1><p class="intro">Handcrafted in London. Designed for your celebration.</p><div class="hero-buttons"><a class="button primary" href="shop.html">Shop cakes <span class="arrow">→</span></a><a class="button" href="custom.html">Create your own</a></div><ul class="hero-facts" aria-label="At a glance"><li>Swiss meringue buttercream</li><li>St Katharine Docks collection</li><li>Bespoke on request</li></ul></div><div class="hero-art"><span class="hero-stage"><img class="hero-cutout" src="assets/hero-cake-stand.png" width="936" height="1031" alt="Reference cake with dark flowers on its polished silver turntable"></span>${badge('ring-hero','HANDCRAFTED IN LONDON · MADE TO CELEBRATE · ')}<a class="hero-pick" href="cake.html?id=${pick.id}"><span class="hero-pick-photo">${image(pick.id)}</span><span class="hero-pick-text"><small>Order online</small><strong>${pick.name}</strong><span>${money(pick.price)} · ${pick.serves} servings</span></span><span class="hero-pick-go" aria-hidden="true">→</span></a></div></div></section><section class="ticker" aria-label="Studio notes"><div class="ticker-track"><div class="ticker-set">${tick}</div><div class="ticker-set" aria-hidden="true">${tick}</div></div></section><section class="wrap featured"><div class="heading-row"><div><p class="eyebrow kicker"><i class="dot" aria-hidden="true"></i>The collection</p><h2 class="section-title">Find your <em>celebration</em></h2></div><a class="text-link" href="shop.html">Shop all cakes <span class="arrow">→</span></a></div><div class="grid bento">${['pink','silver','midnight','raspberry'].map((id,i)=>card(product(id),i)).join('')}</div></section><section class="wrap home-story"><div class="story-photo">${image('raspberry')}</div><div class="story-copy"><p class="eyebrow kicker"><i class="dot" aria-hidden="true"></i>Welcome to</p><h2>GK Cake <em>London</em></h2><p>A cake should feel as special as the moment it marks. From delicate piping to bold sculptural details, find a design that feels like you.</p><p>Choose from the collection, or share your own idea with Elina. We’ll talk through the flavour, size and finishing touches together.</p><div class="signature">Love, GK</div></div></section>${banner()}`}
function title(t,sub=''){return `<div class="page-title"><h1>${t}</h1>${sub?`<p>${sub}</p>`:''}</div>`}
function empty(titleText,copy,href='shop.html',button='Explore the cakes'){return `<div class="empty">${icon('bag')}<h2>${titleText}</h2><p>${copy}</p><a class="button primary" href="${href}">${button} →</a></div>`}
function shop(){return `<div class="wrap">${title('Shop cakes','Handcrafted cakes, made to celebrate.')}<div class="shop-controls"><div class="filters"><label><span class="filter-label">Cake selection</span><select id="filter-mode"><option value="all">All cakes</option><option value="orderable">Order online</option><option value="inspiration">Inspiration</option><option value="unavailable">Unavailable</option></select></label><label><span class="filter-label">Flavour</span><select id="filter-flavour"><option value="all">All flavours</option>${['Vanilla Raspberry','Snickers','Chocolate Raspberry'].map(f=>`<option>${f}</option>`).join('')}</select></label><label><span class="filter-label">Colour</span><select id="filter-colour"><option value="all">All colours</option>${['Pink','Silver','Red','Chocolate','White'].map(f=>`<option>${f}</option>`).join('')}</select></label></div><label><span class="filter-label">Sort by</span><select id="sort" class="sort"><option value="featured">Featured</option><option value="price">Price: low to high</option><option value="name">Name: A–Z</option></select></label></div><div class="date-prompt"><p>${icon('calendar')} <span id="date-caption">${chosenDate()?escape(dateLabel(chosenDate()))+' · demo selection':'Start with your celebration date.'}</span></p><button class="text-link" data-date>Choose date →</button></div><p id="result-count" class="sr-only" role="status"></p><div id="product-grid" class="grid">${PRODUCTS.map(card).join('')}</div><div id="no-results" hidden class="empty"><h2>No cakes match those filters.</h2><p>Try another combination or create something of your own.</p><button id="clear-filters">Clear filters</button></div><p class="catalog-note">Owner-approved processed cake photographs. Three priced products are approved development examples, not live stock.<br>Other cakes are gallery inspiration; flavour, size and final price are agreed with the chef. <a href="sizes.html">Sizes and starting prices</a></p></div>${banner()}`}
// Custom request: Thursday to Sunday dates, three handover modes, pinned photo revision, draft kept for 30 days.
function newReference(){const a='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';let s='';try{const r=crypto.getRandomValues(new Uint8Array(4));for(const x of r)s+=a[x%a.length]}catch{for(let i=0;i<4;i++)s+=a[Math.floor(Math.random()*a.length)]}return 'GKR-'+s}
function exampleDraft(){let d=addDays(TODAY,17);while(weekday(d)!==6)d=addDays(d,1);return{ref:'pink',rev:3,date:d,wedding:false,mode:'collection',slot:'13:00–14:00',servings:'12–14',customServings:'',flavour:'Vanilla Raspberry',colours:'Blush pink and white',channel:'Instagram',reference:'GKR-7Q4M',version:1}}
// Demo seeds: a draft saved yesterday; for the photo states, a Pink piping draft pinned to photo version 3 three days ago.
function loadDraft(){if(DEMO==='draft-restored'&&!readDevice('draft'))saveDraftToDevice(exampleDraft(),Date.now()-26*3600000);if((DEMO==='image-changed'||DEMO==='ref-unavailable')&&!readDevice('draft')&&!params.get('ref'))saveDraftToDevice({...exampleDraft(),reference:'',version:0},Date.now()-3*864e5);return readDevice('draft')}
function hashText(t){let h=0x811c9dc5;for(let i=0;i<t.length;i++){h^=t.charCodeAt(i);h=Math.imul(h,0x01000193)>>>0}return h.toString(16)}
const draftHasContent=d=>!!(d&&(d.date||d.flavour||d.servings||d.reference));
function custom(){return `<div class="wrap">${title('Create your own','Your idea. Our craft. Something unforgettable.')}<div id="draft-banner" class="narrow-banner"></div><div class="form-layout"><section><ol class="steps"><li class="active" id="step-1" aria-current="step">01 · Your cake</li><li id="step-2">02 · Review & send</li></ol>
<form id="custom-form" novalidate><div id="custom-errors" class="co-errors" role="alert" tabindex="-1" hidden></div>
<div id="ref-panel"></div>
<h2 class="cf-h">When and how</h2>
<div class="field request-date"><span id="request-date-label">Your date</span><input id="request-date" name="date" type="hidden" value=""><button class="date-trigger" type="button" data-calendar-toggle="request-date" aria-expanded="false" aria-controls="request-calendar" aria-labelledby="request-date-label request-date-value"><span class="date-value" id="request-date-value">Choose your date</span>${icon('calendar')}</button><div id="request-calendar">${calendar('request-date','','request',true)}</div><p id="request-date-error" class="field-error" hidden>Choose the date you’d like.</p><p id="request-date-note" class="small" role="status"></p></div>
<label class="check-line wedding-line"><input type="checkbox" name="wedding" id="wedding"><span>This is a wedding cake <span class="quiet">(booking 2 to 8 months ahead is normal for weddings)</span></span></label>
${modeSwitch('requestMode','collection')}
<p id="request-mode-note" class="small quiet"></p>
${slotField('request-slot','Preferred time · London time <span class="quiet">(optional)</span>')}
<p class="small quiet">${EXAMPLE_TIMES_NOTE}</p>
<h2 class="cf-h">Your cake</h2>
<fieldset class="field serving-field" id="servings-field" tabindex="-1"><legend>How many servings?</legend><div class="serving-options">${['3–4','7–10','12–14','17–20','30–32','40–45','Other'].map(v=>`<label class="choice-chip"><input type="radio" name="servings" value="${v}"><span>${v}</span></label>`).join('')}</div><label class="field other-servings" hidden>Tell us how many<input name="customServings" id="customServings" type="text" maxlength="80" placeholder="e.g. 60–70 guests" disabled></label><p class="small quiet"><a href="sizes.html">Sizes and starting prices</a></p></fieldset><p id="servings-error" class="field-error" hidden>Choose how many servings.</p>
<div class="two-fields"><div><label class="field">Flavour<select name="flavour" id="flavour"><option value="">Choose a flavour</option>${FLAVOURS.map(f=>`<option>${f}</option>`).join('')}</select></label><p id="flavour-error" class="field-error" hidden>Choose a flavour.</p><p id="flavour-peanuts" class="allergen-alert" hidden>Contains PEANUTS</p></div><label class="field"><span class="field-name">Colour palette <span class="quiet">(optional)</span></span><input name="colours" maxlength="120" placeholder="e.g. white and silver"></label></div>
<label class="field">Describe your cake & important details<textarea name="description" id="description" maxlength="2000" placeholder="Your occasion, design ideas, wording and any important dietary or allergy information." aria-describedby="description-note"></textarea></label><p class="small quiet" id="description-note">Not saved on this device, because it may include allergy or health details. It goes into your request when you send it.</p><p id="description-error" class="field-error" hidden>Tell us a little about the cake you’d like.</p>
<div class="field upload-field"><span id="references-label">Your own photos <span class="quiet">(optional)</span></span><div class="upload-zone" id="upload-zone"><svg class="upload-icon icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="4"/><circle cx="8" cy="8" r="1.5"/><path d="m3 17 6-6 4 4 3-3 5 5"/></svg><strong>A little inspiration goes a long way</strong><span class="small">Drop images here or choose from your device.</span><button type="button" id="browse-references">${icon('plus')} Browse images</button><input type="file" id="references" accept="image/png,image/jpeg,image/webp" multiple hidden aria-labelledby="references-label"><span class="small quiet">JPG, PNG or WebP · several welcome</span></div><p class="small quiet upload-note">Your photos are private design references for the chef. They’re never posted. You’ll be asked about photos of your finished cake later, on your order page. In this preview nothing is uploaded and photos aren’t kept in your draft.</p><p id="reference-error" class="field-error" role="alert" hidden></p><ul id="reference-previews" class="reference-previews" aria-label="Selected photos"></ul><span id="reference-names" class="small" role="status"></span></div>
<fieldset class="field channel-field"><legend>Where would you like to talk?</legend><div class="channel-options"><label class="channel-card"><input type="radio" name="channel" value="Instagram" checked><svg class="channel-icon icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17.5" cy="6.5" r=".8" fill="currentColor" stroke="none"/></svg><span><strong>Instagram</strong><small>Message @gk.cake.london</small></span><span class="choice-check" aria-hidden="true">✓</span></label><label class="channel-card"><input type="radio" name="channel" value="Email"><svg class="channel-icon icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M3 19V5l9 7 9-7v14M3 5v14h4V9m14-4v14h-4V9"/></svg><span><strong>Email</strong><small>gk.cake.london@gmail.com</small></span><span class="choice-check" aria-hidden="true">✓</span></label></div></fieldset>
<p class="small quiet">A request doesn’t reserve your date. The chef agrees the design, flavour, size, date and final price with you before you pay on the website.</p><button class="primary" type="submit">Review my request ${icon('arrow')}</button></form>
<section id="custom-summary" hidden tabindex="-1" aria-labelledby="summary-title"><h2 class="form-heading" id="summary-title">Your request is ready to send</h2><div class="req-card"><div class="req-thumb" id="req-thumb"></div><div><p class="eyebrow">Request reference</p><p class="req-ref" id="req-ref"></p><p class="small quiet" id="req-version"></p><dl class="req-facts" id="req-facts"></dl></div></div><div class="notice" id="req-not-sent"><p><strong>Not sent yet.</strong> Your request reaches the chef when you paste it into Instagram or an email and press send there. It stays on this device so you can come back to it.</p></div><label class="field">Your request text (select and copy it if you need to)<textarea id="summary-text" class="summary-text" readonly></textarea></label><p class="small">Copied text doesn’t include your photos. Attach them in the chat or email; they stay private design references.</p><div class="handoff-actions"><button class="primary" id="handoff-primary" type="button"></button><button id="handoff-secondary" type="button"></button></div><div id="handoff-status" class="notice handoff-status" role="status" tabindex="-1" hidden></div><div class="form-actions"><button id="edit-request" type="button">← Edit request</button><button id="clear-request" type="button" class="text-link">Start a new request</button></div></section></section>
<aside class="form-side inspiration-side" id="custom-side"></aside></div></div>`}

function bindCustom(){
 const form=document.querySelector('#custom-form'),summary=document.querySelector('#custom-summary'),textarea=document.querySelector('#summary-text'),status=document.querySelector('#handoff-status');
 const $=s=>document.querySelector(s);
 const urlRef=params.get('ref'),urlRev=Number(params.get('rev'))||0;
 let draft=loadDraft(),restored=!!draft&&!urlRef&&draftHasContent(draft);
 // Arriving with a different photo (or none) while a saved request exists: ask, never take the draft over silently.
 if(urlRef&&draftHasContent(draft)&&(urlRef==='none'?!!draft.ref:urlRef!==draft.ref&&!!product(urlRef))){const old=product(draft.ref),neu=urlRef==='none'?null:product(urlRef);
  document.querySelector('.form-layout').hidden=true;
  $('#draft-banner').innerHTML=`<section class="draft-choice" aria-labelledby="draft-choice-title" tabindex="-1"><h2 class="form-heading" id="draft-choice-title">You have a saved request</h2><p>${old?`Your saved request uses <strong>${escape(old.name)}</strong>`:'Your saved request has no gallery photo'}${draft.date?` for ${escape(shortDate(draft.date))}`:''}${draft.reference?` (${escape(draft.reference)})`:''}. Continue it, or start a new request ${neu?`with <strong>${escape(neu.name)}</strong>`:'without a photo'}?</p><p class="small quiet">Starting a new one replaces the saved draft on this device.</p><div class="form-actions"><a class="button primary" href="custom.html">Continue my saved request</a><button type="button" id="draft-new">Start a new request</button></div></section>`;
  $('#draft-new').addEventListener('click',()=>{removeDevice('draft');location.reload()});$('.draft-choice').focus();return}
 if(!draft||urlRef&&urlRef!=='none'&&urlRef!==draft.ref)draft={...(draft||{}),ref:'',rev:0,reference:draft?.reference||'',version:draft?.version||0};
 if(urlRef==='none'){draft.ref='';draft.rev=0}
 // Same cake already in the draft: keep the photo version you chose; a newer one is offered, not swapped in.
 if(urlRef&&urlRef!=='none'&&product(urlRef)){const same=draft.ref===urlRef&&draft.rev;draft.ref=urlRef;if(!same)draft.rev=urlRev||currentRev(urlRef)}
 // Demo: a request started with photo version 3 that the chef has since updated, or that can no longer be kept.
 if((DEMO==='image-changed'||DEMO==='ref-unavailable')&&draft.ref==='pink'&&draft.rev>=4&&!urlRev)draft.rev=3;
 let refState=!draft.ref?'none':DEMO==='ref-unavailable'&&draft.rev<currentRev(draft.ref)?'unavailable':draft.rev<currentRev(draft.ref)?'changed':'ok';
 let files=[],attempts=0,lastText='';
 const dateInput=$('#request-date'),cal=document.querySelector('#request-calendar [data-calendar]');
 const modeVal=()=>form.querySelector('[name=requestMode]:checked')?.value||'collection';
 let wantedSlot=draft.slot||'';
 const slots=slotPicker({id:'request-slot',name:'requestSlot',purpose:'request',date:()=>dateInput.value,mode:modeVal,qty:()=>0,selected:()=>wantedSlot,onChange:(v,kind)=>{if(v===null||kind==='error')return;const nv=v||'';if(nv!==wantedSlot){wantedSlot=nv;save()}},onPickDate:d=>{cal.select(d);form.querySelector('[data-calendar-toggle]').focus()}});
 function refPanel(){const p=product(draft.ref),side=$('#custom-side');
  const contact='<hr><p class="small">Instagram: @gk.cake.london<br>Email: gk.cake.london@gmail.com</p><p class="small"><a href="sizes.html">Sizes and starting prices</a></p><p class="small quiet">This preview copies your request but opens no app and sends nothing.</p>';
  if(!p){$('#ref-panel').innerHTML='';side.innerHTML=`${image('lily')}<p class="eyebrow">Made for you</p><h2>Start with an idea</h2><p class="small">You don’t need a photo from our gallery. A clear description is enough to start the conversation. <a href="shop.html?mode=inspiration">Browse inspiration</a></p>${contact}`;return}
  const cur=currentRev(draft.ref);
  if(refState==='changed')$('#ref-panel').innerHTML=`<div class="ref-alert" role="group" aria-labelledby="ref-changed-title"><p id="ref-changed-title"><strong>The chef updated this photo after you chose it.</strong> Your request keeps the photo you chose unless you pick the new one.</p><div class="ref-compare"><figure>${image(draft.ref,revClass(draft.ref,draft.rev))}<figcaption>The photo you chose · version ${draft.rev} <strong>(kept)</strong></figcaption></figure><figure>${image(draft.ref,revClass(draft.ref,cur))}<figcaption>Current photo · version ${cur}</figcaption></figure></div><div class="form-actions"><button type="button" id="ref-keep" class="primary">Keep the photo I chose</button><button type="button" id="ref-new">Use the current photo</button></div></div>`;
  else if(refState==='unavailable')$('#ref-panel').innerHTML=`<div class="ref-alert error" role="group" aria-labelledby="ref-gone-title" id="ref-choice" tabindex="-1"><p id="ref-gone-title"><strong>The photo you chose (version ${draft.rev}) is no longer available</strong>, so it can’t go into your request. Choose the current photo, or continue without one.</p><div class="ref-compare one"><figure>${image(draft.ref,revClass(draft.ref,cur))}<figcaption>Current photo · version ${cur}</figcaption></figure></div><div class="form-actions"><button type="button" id="ref-new">Use the current photo</button><button type="button" id="ref-none">Continue without a photo</button></div></div>`;
  else $('#ref-panel').innerHTML=`<div class="ref-pin">${image(draft.ref,revClass(draft.ref,draft.rev))}<div><p class="eyebrow">Your starting point</p><h3>${p.name}</h3><p class="small">Your request includes this exact photo (version ${draft.rev}). We won’t swap it without asking you.</p><button type="button" class="text-link" id="ref-remove">Remove this photo</button></div></div>`;
  side.innerHTML=`${image(draft.ref,revClass(draft.ref,draft.rev))}<p class="eyebrow">Your starting point</p><h2>${p.name}</h2><p class="small">Tell us what you’d like to change: size, flavour, colours, wording or decoration.</p>${contact}`;
  $('#ref-keep')?.addEventListener('click',()=>{refState='ok';save();refPanel();$('#ref-remove')?.focus()});
  $('#ref-new')?.addEventListener('click',()=>{draft.rev=cur;refState='ok';save();refPanel();$('#ref-remove')?.focus()});
  $('#ref-none')?.addEventListener('click',()=>{draft.ref='';draft.rev=0;refState='none';save();refPanel();form.querySelector('[data-calendar-toggle]').focus()});
  $('#ref-remove')?.addEventListener('click',()=>{draft.ref='';draft.rev=0;refState='none';save();refPanel();form.querySelector('[data-calendar-toggle]').focus();toast('Photo removed from your request.')});
 }
 function dateNote(){const d=dateInput.value,wed=form.elements.wedding.checked,n=$('#request-date-note');if(!d){n.textContent='';return}n.textContent=d<SHORT_NOTICE?`${shortDate(d)} is less than 8 days away. You can still ask; the chef will confirm.`:d>HORIZON?(wed?`${shortDate(d)} is more than 2 months ahead, which is normal for a wedding cake (up to 8 months ahead).`:`${shortDate(d)} is more than 2 months ahead. You can ask up to 8 months ahead; the chef will confirm.`):`${shortDate(d)}. The chef confirms your date when you agree the details.`}
 function modeNote(){$('#request-mode-note').textContent={collection:'Collect for free from St Katharine Docks. The full address is sent privately before your date.',courier:'You book and pay your own courier to collect from St Katharine Docks. Responsibility passes to them at handover.',delivery:'The chef checks whether delivery to your address is possible and quotes it (from £100). It is paid separately. Times are requested, the chef confirms.'}[modeVal()]}
 function values(){const d=new FormData(form);return{ref:draft.ref,rev:draft.rev,date:dateInput.value,wedding:form.elements.wedding.checked,mode:modeVal(),slot:wantedSlot,servings:d.get('servings')||'',customServings:(d.get('customServings')||'').trim(),flavour:d.get('flavour')||'',colours:(d.get('colours')||'').trim(),description:(d.get('description')||'').trim(),channel:d.get('channel')||'Instagram',reference:draft.reference||'',version:draft.version||0,frozen:draft.frozen||''}}
 // Saved only on real edits (opening the page never resets the 30-day clock); the description is never saved.
 function save(){draft={...draft,...values()};saveDraftToDevice(draft)}
 // Restore the draft into the form.
 form.elements.wedding.checked=!!draft.wedding;cal.dataset.wedding=String(!!draft.wedding);
 if(draft.date&&dayInfo(draft.date,'request',0).enabled){cal.select(draft.date)}
 if(draft.mode){const r=form.querySelector(`[name=requestMode][value="${draft.mode}"]`);if(r)r.checked=true}
 if(draft.servings){const r=form.querySelector(`[name=servings][value="${draft.servings}"]`);if(r)r.checked=true}
 const other=form.querySelector('.other-servings'),customServings=form.elements.customServings;
 function syncOther(){const show=form.elements.servings.value==='Other';other.hidden=!show;customServings.disabled=!show}
 customServings.value=draft.customServings||'';syncOther();
 form.elements.flavour.value=draft.flavour||'';form.elements.colours.value=draft.colours||'';form.elements.description.value=draft.description||'';
 if(draft.channel)form.querySelector(`[name=channel][value="${draft.channel}"]`).checked=true;
 $('#flavour-peanuts').hidden=form.elements.flavour.value!=='Snickers';
 refPanel();dateNote();modeNote();slots.refresh();
 if(restored)$('#draft-banner').innerHTML=`<div class="notice draft-banner" role="status"><p><strong>Draft restored.</strong> We kept your request from ${escape(new Date(draft.saved).toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short',timeZone:'Europe/London'}))} on this device (drafts are kept for 30 days). Photos and your description aren’t kept (the description may include allergy or health details), so please add them again.${draft.reference?` Reference ${escape(draft.reference)}.`:''}</p><button type="button" class="text-link" id="draft-clear">Start again</button></div>`;
 $('#draft-clear')?.addEventListener('click',()=>{removeDevice('draft');location.href='custom.html'});
 // Live updates.
 dateInput.addEventListener('input',()=>{dateNote();slots.refresh();save();clearErr('request-date')});
 form.elements.wedding.addEventListener('change',()=>{cal.dataset.wedding=String(form.elements.wedding.checked);cal.repaint();dateNote();save()});
 form.querySelectorAll('[name=requestMode]').forEach(r=>r.addEventListener('change',()=>{modeNote();slots.refresh();save()}));
 form.querySelectorAll('[name=servings]').forEach(r=>r.addEventListener('change',()=>{syncOther();if(form.elements.servings.value==='Other')customServings.focus();clearErr('servings');save()}));
 form.elements.flavour.addEventListener('change',()=>{$('#flavour-peanuts').hidden=form.elements.flavour.value!=='Snickers';clearErr('flavour');save()});
 ['colours','description','customServings'].forEach(n=>form.elements[n].addEventListener('input',()=>{if(n==='description')clearErr('description');save()}));
 form.querySelectorAll('[name=channel]').forEach(r=>r.addEventListener('change',save));
 // Local photo previews (never stored in the draft, never uploaded).
 const upload=$('#references'),zone=$('#upload-zone'),previews=$('#reference-previews'),error=$('#reference-error'),browse=$('#browse-references');
 function showFiles(){previews.innerHTML=files.map((f,i)=>`<li><img src="${f.url}" alt=""><span>${escape(f.file.name)}<small>${Math.max(1,Math.round(f.file.size/1024))} KB · on this page only</small></span><button type="button" data-remove-file="${i}" aria-label="Remove ${escape(f.file.name)}">×</button></li>`).join('');$('#reference-names').textContent=files.length?`${files.length} photo${files.length===1?'':'s'} added. Nothing uploaded.`:''}
 function addFiles(incoming){let rejected=false;for(const file of incoming){if(!['image/png','image/jpeg','image/webp'].includes(file.type)){rejected=true;continue}if(!files.some(f=>f.file.name===file.name&&f.file.size===file.size&&f.file.lastModified===file.lastModified))files.push({file,url:URL.createObjectURL(file)})}error.hidden=!rejected;error.textContent=rejected?'Please choose JPG, PNG or WebP images. Other files weren’t added.':'';showFiles();upload.value=''}
 browse.addEventListener('click',()=>upload.click());upload.addEventListener('change',()=>addFiles(Array.from(upload.files)));
 zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('dragging')});zone.addEventListener('dragleave',()=>zone.classList.remove('dragging'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragging');addFiles(Array.from(e.dataTransfer.files))});
 previews.addEventListener('click',e=>{const b=e.target.closest('[data-remove-file]');if(!b)return;const i=Number(b.dataset.removeFile);URL.revokeObjectURL(files[i].url);files.splice(i,1);showFiles();(previews.querySelector(`[data-remove-file="${Math.min(i,files.length-1)}"]`)||browse).focus()});
 window.addEventListener('pagehide',()=>files.forEach(f=>URL.revokeObjectURL(f.url)));
 // Validation with an error summary.
 function showErr(id){$('#'+id+'-error').hidden=false;const el=id==='request-date'?form.querySelector('[data-calendar-toggle]'):$('#'+id)||$('#'+id+'-field');el?.setAttribute('aria-invalid','true')}
 function clearErr(id){const m=$('#'+id+'-error');if(m)m.hidden=true;($('#'+id)||$('#'+id+'-field'))?.removeAttribute('aria-invalid')}
 const handover=m=>({collection:'Collect from St Katharine Docks',courier:'My own courier collects from St Katharine Docks',delivery:'GK delivery (quoted by the chef, from £100, paid separately)'}[m]);
 function requestText(v){const p=product(v.ref),servings=v.servings==='Other'?v.customServings:v.servings;const dn=v.date<SHORT_NOTICE?' (less than 8 days away; the chef will confirm)':v.date>HORIZON&&!v.wedding?' (more than 2 months ahead; the chef will confirm)':'';return['Hello GK Cake London! I’d like to request a cake.',`Request reference: ${v.reference}${v.version>1?` (version ${v.version})`:''}`,`Date: ${longDate(v.date)}${dn}`,...(v.wedding?['Wedding cake: yes']:[]),`Handover: ${handover(v.mode)}`,`Preferred time: ${v.slot?v.slot+' London time'+(v.mode==='delivery'?' (requested, the chef confirms)':' (the chef confirms)'):'to agree with the chef'}`,`Servings: ${servings}`,`Flavour: ${v.flavour}${v.flavour==='Snickers'?' (contains PEANUTS)':''}`,`Colours: ${v.colours||'to discuss'}`,p?`Starting point: ${p.name}, GK photo ${imgOf(p)} version ${v.rev}`:'Starting point: my description (no gallery photo)',`Details: ${v.description}`,`My own photos: ${files.length?files.length+' (I’ll attach them here)':'none'}`,'I understand the design, date and final price are agreed with the chef before I pay.'].join('\n')}
 function thumb(v){const p=product(v.ref);if(p)return `${image(v.ref,revClass(v.ref,v.rev))}<p class="small quiet">${escape(p.name)} · photo version ${v.rev}</p>`;if(files.length)return `<img src="${files[0].url}" alt="Your first photo"><p class="small quiet">Your photo (on this page only)</p>`;return '<p class="small quiet no-thumb">No photo: description only</p>'}
 function showSummary(){const v=draft;textarea.value=requestText(v);$('#req-ref').textContent=v.reference;$('#req-version').textContent=v.version>1?`Version ${v.version}: updated after your changes. Same reference.`:'Version 1';$('#req-thumb').innerHTML=thumb(v);$('#req-facts').innerHTML=[['Date',shortDate(v.date)+(v.date<SHORT_NOTICE||v.date>HORIZON&&!v.wedding?' · the chef will confirm':'')],['Handover',{collection:'Collect · St Katharine Docks',courier:'Own courier',delivery:'GK delivery · quoted by the chef'}[v.mode]],['Time',v.slot?v.slot+(v.mode==='delivery'?' · requested, the chef confirms':' · the chef confirms'):'To agree'],['Servings',v.servings==='Other'?v.customServings:v.servings],['Flavour',v.flavour]].map(([k,x])=>`<div><dt>${k}</dt><dd>${escape(x)}</dd></div>`).join('');const ig='Copy request & open Instagram',em='Copy request & open email';$('#handoff-primary').textContent=v.channel==='Email'?em:ig;$('#handoff-primary').dataset.kind=v.channel==='Email'?'email':'instagram';$('#handoff-secondary').textContent=v.channel==='Email'?ig:em;$('#handoff-secondary').dataset.kind=v.channel==='Email'?'instagram':'email';status.hidden=true;attempts=0;form.hidden=true;summary.hidden=false;$('#step-1').classList.remove('active');$('#step-1').removeAttribute('aria-current');$('#step-2').classList.add('active');$('#step-2').setAttribute('aria-current','step');summary.focus();summary.scrollIntoView({block:'start'})}
 form.addEventListener('submit',e=>{e.preventDefault();const v=values(),errs=[];
  if(refState==='unavailable')errs.push(['ref-choice','Choose a photo option for your starting point']);
  if(!v.date){showErr('request-date');errs.push(['request-date','Choose the date you’d like'])}
  if(!v.servings||v.servings==='Other'&&!v.customServings){showErr('servings');errs.push(['servings-field','Choose how many servings'])}
  if(!v.flavour){showErr('flavour');errs.push(['flavour','Choose a flavour'])}
  if(!v.description){showErr('description');errs.push(['description','Tell us a little about the cake'])}
  const box=$('#custom-errors');if(errs.length){box.hidden=false;box.innerHTML=`<p><strong>Please check ${errs.length===1?'1 thing':errs.length+' things'}</strong></p><ul>${errs.map(([id,t])=>`<li><a href="#${id}">${t}</a></li>`).join('')}</ul>`;box.focus();return}box.hidden=true;
  // One reference per request; editing after review keeps the reference and adds a version. Retrying the handoff never makes a new one.
  const content=hashText(JSON.stringify({...v,reference:'',version:0,frozen:''}));
  if(!draft.reference){draft.reference=newReference();draft.version=1}else if(draft.frozen&&draft.frozen!==content){draft.version=(draft.version||1)+1}else if(!draft.version){draft.version=1}
  draft={...draft,...v,reference:draft.reference,version:draft.version,frozen:content};saveDraftToDevice(draft);showSummary()});
 $('#custom-errors').addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(!a)return;e.preventDefault();const t=document.getElementById(a.getAttribute('href').slice(1));if(a.getAttribute('href')==='#request-date')form.querySelector('[data-calendar-toggle]').focus();else(t?.matches('fieldset')?t.querySelector('input'):t)?.focus()});
 $('#edit-request').addEventListener('click',()=>{summary.hidden=true;form.hidden=false;$('#step-2').classList.remove('active');$('#step-2').removeAttribute('aria-current');$('#step-1').classList.add('active');$('#step-1').setAttribute('aria-current','step');form.querySelector('[data-calendar-toggle]').focus()});
 $('#clear-request').addEventListener('click',()=>{removeDevice('draft');location.href='custom.html?ref=none'});
 // "Copy request & open Instagram / email": one gesture, honest outcomes, same request on every retry.
 async function copy(text){if(DEMO==='copy-failed'||DEMO==='both-failed')return false;try{if(!navigator.clipboard)return false;return await Promise.race([navigator.clipboard.writeText(text).then(()=>true),wait(1500).then(()=>false)])}catch{return false}}
 async function handoff(kind){attempts++;const v=draft;const copied=await copy(textarea.value);const opened=!(DEMO==='open-failed'||DEMO==='both-failed');const ig=kind==='instagram';const app=ig?'Instagram':'your email app';const where=ig?'the chat with @gk.cake.london':`a new email to gk.cake.london@gmail.com (subject “Cake request ${v.reference}”)`;
  let html;
  if(copied&&opened)html=`<p><strong>Copied.</strong> ${ig?'Instagram':'Your email app'} should now be open at ${where}. Paste your request and press send there.</p><p class="small">${ig?'Instagram':'Email'} didn’t open? <button type="button" class="text-link" data-retry="${kind}">Try again</button> or ${ig?'open Instagram yourself and search @gk.cake.london':'write to gk.cake.london@gmail.com yourself'}.</p>`;
  else if(!copied&&opened)html=`<p><strong>We couldn’t copy your request automatically.</strong> ${ig?'Instagram':'Your email app'} should now be open. Select the text above, copy it, then paste it into ${where}.</p><p class="small">${ig?'Instagram':'Email'} didn’t open? <button type="button" class="text-link" data-retry="${kind}">Try again</button></p>`;
  else if(copied&&!opened)html=`<p><strong>Copied, but ${app} didn’t open.</strong> ${ig?'Open Instagram yourself, find @gk.cake.london and paste your request.':'Write to gk.cake.london@gmail.com and paste your request; please put '+escape(v.reference)+' in the subject.'}</p><p><button type="button" data-retry="${kind}">Try again</button></p>`;
  else html=`<p><strong>We couldn’t copy your request or open ${app}.</strong> Your request ${escape(v.reference)} is still here. Select the text above and copy it, then message @gk.cake.london on Instagram or email gk.cake.london@gmail.com.</p><p><button type="button" data-retry="${kind}">Try again</button></p>`;
  html+=`<p class="small quiet">Same request ${escape(v.reference)}${attempts>1?` · attempt ${attempts}`:''}: trying again doesn’t create a new request. Nothing has been sent. Preview only: no app was opened.</p>`;
  status.className='notice handoff-status'+(copied&&opened?'':' error');status.hidden=false;status.innerHTML=html;
  if(!copied){textarea.focus();textarea.select()}else status.focus();
  status.querySelectorAll('[data-retry]').forEach(b=>b.addEventListener('click',()=>handoff(b.dataset.retry)))}
 $('#handoff-primary').addEventListener('click',e=>handoff(e.currentTarget.dataset.kind));
 $('#handoff-secondary').addEventListener('click',e=>handoff(e.currentTarget.dataset.kind));
}
function bagPage(){const items=bag().map(product);return `<div class="wrap">${title('Your bag',items.length?'A celebration in the making.':'A little room for something special.')} ${!items.length?empty('Your bag is waiting','Explore the cakes, choose a date and find your favourite.'):`<div class="form-layout"><div>${items.map(p=>`<article class="bag-row">${image(p.id)}<div><h2><a href="cake.html?id=${p.id}">${p.name}</a></h2><p>${p.flavour} · ${p.serves} servings</p><p>Quantity: 1 · ${p.size}</p><button class="remove" data-remove="${p.id}">Remove ${p.name}</button></div><span>${money(p.price)}</span></article>`).join('')}<a class="text-link" href="shop.html">← Continue shopping</a></div><aside class="form-side"><h2>Your celebration</h2><p class="small">${escape(dateLabel(chosenDate()))} · London time</p><button class="text-link" data-date>Change date →</button><div class="totals"><span>Cakes</span><span>${money(items.reduce((n,p)=>n+p.price,0))}</span></div><div class="totals"><span>Collection</span><span>Free</span></div><div class="totals total"><span>Cake total</span><span>${money(items.reduce((n,p)=>n+p.price,0))}</span></div><p class="small quiet">Decoration shown included. GK delivery is separately quoted and paid; it is not included in this cake total.</p><a class="button primary" href="checkout.html">Review checkout ${icon('arrow')}</a><p class="small quiet">Demo bag only. Nothing reserved or purchased.</p></aside></div>`}</div>`}
function checkout(){const existing=read('order',null);if(['pending','late'].includes(existing?.state))return `<div class="wrap">${title('Your payment needs a result')}<div class="narrow"><div class="notice">${existing.state==='pending'?'This demo payment is still unknown. Do not start another payment.':'Payment was received; date agreement is pending. Do not pay again.'}</div><a class="button primary" href="order.html">View current status →</a><p class="small quiet">To test a different scenario, explicitly clear demo data on the policy preview page.</p></div></div>`;const items=bag().map(product);if(!items.length)return `<div class="wrap">${title('Checkout')}${empty('Your bag is empty','Choose a cake before previewing checkout.')}</div>`;const sub=items.reduce((n,p)=>n+p.price,0);const methods=['Cards','Apple Pay','Onelink','Klarna','Revolut Pay','Amazon Pay','Cartes Bancaires','Samsung Pay','Satispay','MB WAY','Bancontact','BLIK','EPS','Pix','Kakao Pay','Naver Pay','PAYCO'];
return `<div class="wrap checkout-page">${title('Checkout','Guest checkout · nothing is charged in this preview.')}<ol class="steps co-steps"><li>01 · Bag</li><li class="active" aria-current="step">02 · Checkout</li><li>03 · Secure payment</li><li>04 · Confirmation</li></ol><p class="co-step-short">Step 2 of 4 · Checkout</p><a class="co-mobile-total" href="#sum-title"><span id="sum-total-top-label">To pay now</span><strong id="sum-total-top">${money(sub)}</strong><span class="co-mobile-link">View order<span aria-hidden="true"> ↓</span></span></a><div class="checkout-layout"><form id="checkout-form" novalidate><div id="error-summary" class="co-errors" role="alert" tabindex="-1" hidden></div>
<section class="co-card"><h2 class="co-h"><span class="co-num" aria-hidden="true">1</span>When and how</h2><div class="co-date"><span>${icon('calendar')} <strong>${escape(dateLabel(chosenDate()))}</strong> · London time</span><button class="text-link" type="button" data-date>Change date</button></div><fieldset class="co-modes"><legend class="sr-only">How you will get your cake</legend><label class="mode-card"><input type="radio" name="fulfilment" value="collection" checked><span><strong>Collect · Free</strong><small>St Katharine Docks, London.</small></span></label><label class="mode-card"><input type="radio" name="fulfilment" value="courier"><span><strong>Your own courier</strong><small>You book and pay your courier to collect at your time. Responsibility passes to them at handover.</small></span></label><label class="mode-card"><input type="radio" name="fulfilment" value="delivery"><span><strong>GK delivery · from £100</strong><small>The chef quotes for your address. Delivery is paid separately.</small></span></label></fieldset><fieldset class="slot-field co-slot-field" id="slot" tabindex="-1" aria-describedby="slot-status"><legend id="checkout-slot-label">Collection time · London time</legend><p id="slot-status" class="small quiet co-status" role="status"></p><div class="slot-list" id="slot-list"></div><div class="slot-extra" id="slot-extra"></div></fieldset><p id="slot-error" class="field-error" hidden>Choose a time.</p><div id="delivery-note" class="notice co-delivery-note" hidden><p><strong>Pay for your cakes now, delivery afterwards.</strong> After payment, the chef confirms your address and delivery time and sends a delivery quote (from £100) to pay separately, unless a free-delivery code is approved.</p><p class="small">The time you choose is a request until the chef confirms it.</p></div><div id="address-field" hidden><label class="field">Delivery address<textarea id="address" name="address" autocomplete="street-address" maxlength="300" rows="3"></textarea></label><p id="address-error" class="field-error" hidden>Enter the delivery address, including the postcode.</p><p class="small quiet">The chef uses this to confirm and quote delivery. Preview only: not saved.</p></div></section>
<section class="co-card"><h2 class="co-h"><span class="co-num" aria-hidden="true">2</span>Your details</h2><div class="two-fields"><div><label class="field">Full name<input id="name" name="name" autocomplete="name" maxlength="80"></label><p id="name-error" class="field-error" hidden>Enter your full name.</p></div><div><label class="field">Email for order updates<input id="email" name="email" type="email" autocomplete="email" maxlength="120"></label><p id="email-error" class="field-error" hidden>Enter an email address like name@example.com.</p></div></div><label class="check-line co-payer-toggle"><input type="checkbox" name="otherPayer" id="other-payer"><span>Someone else is paying <span class="quiet">(we record who paid)</span></span></label><div id="payer-field" hidden><label class="field">Payer’s full name<input id="payer" name="payer" autocomplete="off" maxlength="80"></label><p id="payer-error" class="field-error" hidden>Enter the payer’s full name.</p></div><p class="small quiet">Preview only: these details stay on this page. Nothing is sent or saved.</p></section>
<section class="co-card"><h2 class="co-h"><span class="co-num" aria-hidden="true">3</span>Discount code <span class="co-optional">optional</span></h2><div class="code-row" id="code-row"><label class="field"><span class="sr-only">Discount code</span><input name="code" id="code-input" autocomplete="off" maxlength="30" placeholder="Enter a code" aria-describedby="code-status"></label><button type="button" id="apply-code">Apply</button></div><div class="code-chip" id="code-applied" hidden><span id="code-chip-text" tabindex="-1"></span><button type="button" class="text-link" id="remove-code">Remove</button></div><p id="code-status" class="small code-status" role="status">One code per order. Try the example code <strong>DEMO10</strong>.</p></section>
<section class="co-card"><h2 class="co-h"><span class="co-num" aria-hidden="true">4</span>Before you pay</h2>${items.map(p=>`<div class="co-allergen"><p class="co-label">${p.name} · allergens</p>${p.id==='chocolate'?'<p class="allergen-alert">Contains PEANUTS</p>':''}<p><strong>Contains: EGGS, MILK, CEREALS CONTAINING GLUTEN (WHEAT), SOYBEANS${p.id==='chocolate'?', PEANUTS':''}.</strong></p><p class="small">${p.composition} Swiss meringue buttercream.</p></div>`).join('')}<p class="cross-contact small">${NOTICE}</p><div class="co-policy" id="refund-terms"><p class="co-label">Cancellation and refunds</p><p>Choose a time to see your exact cancellation deadline.</p></div><p class="small quiet co-statutory">Nothing in this cancellation and refund policy affects the customer’s statutory rights where a product is faulty, not as described or otherwise does not meet applicable legal requirements.</p><label class="check-line co-confirm"><input type="checkbox" id="reviewed" name="reviewed"><span>I’ve checked the cake, allergens, date and the refund terms above. <a href="policies.html" target="_blank" rel="noopener">Full policies<span class="sr-only"> (opens in a new tab)</span> ↗</a></span></label><p id="reviewed-error" class="field-error" hidden>Tick to confirm you’ve checked your order.</p></section>
<section class="co-card"><h2 class="co-h"><span class="co-num" aria-hidden="true">5</span>Payment</h2><p class="co-lead">You’ll pay on our secure payment page, which shows the options available to you.</p><p class="co-methods-label">Ways to pay include:</p><p class="pay-list">${methods.slice(0,6).join(' · ')}</p><details class="pay-all"><summary>Show all ${methods.length} methods</summary><p class="pay-list">${methods.join(' · ')}</p></details><p class="preview-note small">Preview note: the method list is still being confirmed with our payment provider.</p><p class="small quiet">Prices and refunds are in pounds (GBP). Some options charge in another currency; the payment page shows the converted amount and any fees before you pay.</p></section>
<details class="review-tools"><summary>Design review only · choose what the payment page returns</summary><label class="field">Simulated result<select name="outcome"><option value="success">Payment confirmed</option><option value="pending">Payment result unknown</option><option value="late">Paid too late for the preparation time · date awaiting agreement</option><option value="changed">Price changed before payment</option><option value="failed">Payment failed</option><option value="expired">Payment link expired</option><option value="recovery">Checkout temporarily unavailable</option></select></label><p class="small quiet">Not a payment method choice. No payment provider is contacted.</p></details>
</form><aside class="co-summary" aria-labelledby="sum-title"><h2 id="sum-title">Your order</h2>${items.map(p=>`<div class="sum-item">${image(p.id)}<div><strong>${p.name}</strong><span>${p.flavour} · ${p.size} · ${p.serves} servings</span></div><span class="sum-price">${money(p.price)}</span></div>`).join('')}<dl class="sum-meta"><div><dt>Date</dt><dd>${escape(dateLabel(chosenDate()))}</dd></div><div><dt>Time</dt><dd id="sum-time">Choose a time</dd></div><div><dt>How you’ll get it</dt><dd id="sum-mode">Collect · St Katharine Docks</dd></div></dl><div class="totals"><span>Cakes</span><span id="sum-sub">${money(sub)}</span></div><div class="totals" id="sum-discount-row" hidden><span id="sum-discount-label">Discount</span><span id="sum-discount"></span></div><div class="totals"><span id="sum-fulfil-label">Collection</span><span id="sum-fulfil">Free</span></div><div class="totals total"><span id="sum-total-label">To pay now</span><span id="sum-total">${money(sub)}</span></div><p class="small quiet" id="sum-note">In pounds (GBP). Decoration shown is included.</p><ul class="co-assure"><li id="assure-hold">Your place on this date is held for 15 minutes while you pay. If your payment is still processing after that, we’ll wait for the result.</li><li id="assure-confirm">Your order is confirmed only when we receive the payment. We’ll email you.</li><li id="assure-twice">If a payment result is unclear, we check it for you. Please don’t pay twice.</li></ul><button type="submit" form="checkout-form" class="primary co-pay" id="preview-payment"><span id="pay-label">Continue to secure payment · ${money(sub)}</span> ${icon('arrow')}</button><p id="pay-status" class="sr-only" role="status"></p></aside></div></div>`}
function orderPage(){const raw=read('order',null);const example=params.get('example')==='true';const o=example?{items:['pink'],date:FIRST_LEAD_DAY,slot:demoSlots(FIRST_LEAD_DAY)[0]||'11:00–12:00',state:'success',mode:'collection'}:raw;if(!o||!Array.isArray(o.items))return `<div class="wrap">${title('Your order')}${empty('No order preview yet','Complete the demo checkout to explore order states.')}</div>`;const items=o.items.map(product).filter(Boolean);const state=['success','pending','late','failed','expired','recovery','changed','cancelled'].includes(o.state)?o.state:'pending';const copy={success:['A moment to look forward to','Simulated order confirmation. No payment was taken and no order or email was created.'],pending:['We’re checking your payment','Demo: the result is unknown. Do not pay again. Wait for a confirmed result; a redirect or expired hold is not payment failure.'],late:['Payment received. Let’s agree your date.','Demo: payment is known successful, but the date needs review. The chef checks feasibility and you explicitly agree; otherwise a full refund is due. Preparation and fulfilment wait.'],changed:['Please review the latest price','Demo: the catalogue price changed before payment. A fresh quote and your agreement to its current total are required. Nothing was paid. Accepted order totals stay unchanged.'],failed:['That payment didn’t go through','Demo: a definitive payment failure. Your cake selection is retained.'],expired:['This payment link has expired','Demo: the 24-hour window for starting payment has ended. Ask the chef for a newly reviewed agreement. An already in-flight payment would keep waiting.'],recovery:['Checkout is temporarily unavailable','Demo: no new payment can start while recovery readiness is unavailable. Your cake selection is retained.'],cancelled:['Cancellation requested in this demo','This local simulation did not cancel a real order or return money. Refund requested and refund completed are distinct states.']}[state];return `<div class="wrap">${title(copy[0])}<div class="narrow"><div class="notice ${state==='success'?'success':''}">${copy[1]}</div><p class="eyebrow">DEMO-001 · Simulated ${example?'account example':'checkout'}</p><div class="content-banner"><h2>${items.map(p=>p.name).join(' & ')}</h2><p>${escape(dateLabel(o.date))} · ${escape(o.slot||'Time to agree')} · London time</p>${o.discount?`<p>Discount${o.code?' · '+escape(o.code):''}: <strong>−${money(o.discount)}</strong></p>`:''}<p>${state==='changed'?'Previous cake total':'Cake total'}: <strong>${money(Number.isInteger(o.total)?o.total:items.reduce((n,p)=>n+p.price,0))}</strong></p><p>${o.mode==='courier'?'Customer-arranged courier':o.mode==='delivery'?'GK delivery · time requested, chef to confirm and send the delivery quote':'Collection from St Katharine Docks'}</p></div>${state==='success'?`<ol class="timeline"><li class="done"><strong>Confirmed · demo</strong><br>Payment and date agreed in this scenario.</li><li>Preparation<br>Chef confirms the start; the automatic clock is 48 hours after cake payment.</li><li>Ready for your celebration<br>Collection details follow separately.</li></ol><div class="form-actions">${o.mode==='delivery'?'':'<button id="change-time">Preview time change</button>'}<button id="cancel-preview">Preview cancellation</button></div>${o.mode==='delivery'?'<p class="small">Need a different delivery time? Please contact the chef: delivery times are agreed with the chef.</p>':''}<div id="order-action" hidden class="notice" role="status"></div>`:state==='late'?'<div class="notice">Awaiting chef feasibility and your explicit agreement. No automatic date change or production start.</div>':state==='pending'?'<button disabled>Waiting for the payment result</button>':state==='changed'?'<div class="notice">An updated server quote is required before continuing. This local POC does not invent a new price or accept payment.</div><a class="button" href="shop.html">Review the cakes →</a>':state==='cancelled'?'<p class="small">A cancelled order cannot be reopened. A new order needs a new agreement.</p>':'<a class="button" href="bag.html">Return to your retained bag →</a>'}<a class="text-link" href="shop.html">Continue exploring →</a><p class="small quiet">This is a local state preview, not evidence of money movement, reservation, account access or a sent email.</p></div></div>`}
