function account(){const favs=saved().length;
 if(DEMO!=='signed-in')return `<div class="wrap">${title('Your account','Sign in to see your orders and keep your favourites in one place.')}<div class="account-grid"><section class="account-panel"><h2>Sign in or create an account</h2><p class="small">Enter your email and we’ll send you a sign-in link. If you’re new, the link creates your account.</p><form id="signin-preview" novalidate><label class="field">Email<input type="email" name="email" autocomplete="email" maxlength="120"></label><button class="primary" type="submit">Email me a sign-in link</button></form><p class="or-line" aria-hidden="true"><span>or</span></p><button type="button" id="google-preview" class="google-button"><span class="g-badge" aria-hidden="true">G</span> Continue with Google</button><p id="signin-status" class="small quiet" role="status">Preview: sign-in is designed in the next sketch (r02). Nothing is sent.</p></section><section class="account-panel"><h2>Ordered as a guest or on Instagram?</h2><p class="small">Once you’re signed in, you can add an older order to your account: open the private link in your order email, or send the chef your order reference with a short note. The chef checks it before adding it, and can also add an order for you if you ask.</p><h2>Your favourites</h2><p class="small">${favs?`You have ${favs} saved on this device.`:'Nothing saved yet.'} Favourites stay on this device for a year. When you sign in, you can choose to add them to your account.</p><a class="button" href="favourites.html">View favourites (${favs}) →</a></section></div><div class="narrow"><h2>Order again</h2><p>Sign in to see your past orders. When you order again, we show today’s price, allergens and dates before you pay.</p><a class="button" href="reorder.html">See an example →</a></div></div>`;
 const d=pastOrderDate();
 return `<div class="wrap">${title('Your account','Signed in as anna@example.com · example account for design review')}<div class="account-grid"><section class="account-panel"><h2>Your orders</h2><article class="history-row"><div><p class="eyebrow">DEMO-014 · Collected</p><p><strong>Pink piping, Chocolate swirl, Raspberry ribbons</strong></p><p class="small">${escape(dateLabel(d))} · Collection · ${money(28500)} paid</p></div><a class="button primary" href="reorder.html?order=DEMO-014">Order again →</a></article><p class="small quiet">Full history, order details and claiming older orders come in the next sketch (r02).</p></section><section class="account-panel"><h2>Your favourites</h2>${favs?`<p class="small">${favs} saved on this device. Add them to your account on the favourites page; nothing is added until you choose.</p>`:'<p class="small">Nothing saved yet.</p>'}<a class="button" href="favourites.html?demo=signed-in">View favourites (${favs}) →</a></section></div></div>`}
function mergePanel(n){return `<div class="notice merge-panel" id="merge-panel"><div><p><strong>Add ${n===1?'this favourite':`these ${n} favourites`} from this device to your account?</strong> Then they’ll show wherever you sign in. Nothing changes until you choose.</p><div class="form-actions"><button class="primary" type="button" id="merge-yes">Add to my account</button><button type="button" id="merge-no">Keep on this device only</button></div></div></div>`}
function favourites(){const items=saved().map(product),v=readDevice('favourites'),until=v?.expires?dateLabel(londonParts(Date.parse(v.expires)).year+'-'+londonParts(Date.parse(v.expires)).month+'-'+londonParts(Date.parse(v.expires)).day):'';const signedIn=DEMO==='signed-in';
 return `<div class="wrap">${title('Your favourites','A little collection of cakes you love.')}${items.length?`${signedIn?mergePanel(items.length):''}<div class="grid">${items.map(card).join('')}</div><p class="catalog-note">Saved on this device for a year (until ${escape(until)}).${signedIn?'':' Sign in to choose whether to add them to your account.'} Check today’s details before ordering.</p>`:empty('Find something you love','Tap the heart on a cake to save it on this device.')}</div>`}
// Public guide (Creator answer 3). Values are GK-002 base prices; the chef sets sizes and prices per cake.
function sizes(){const rows=[['Mini','5 inches','3–4','1–1.3 kg',7000],['S','6 inches','7–10','1.5–1.7 kg',9000],['M','7 inches','12–14','2.2–2.7 kg',10500],['L','8 inches','17–20','3–3.8 kg',13000],['XL','10 inches','30–32','5–6 kg',18000],['XXL','12 inches','40–45','8–9 kg',24500]],tiers=[['4 + 7 inches','14–17',18000],['6 + 8 inches','28–32',25000],['8 + 10 inches','47–53',32000],['4 + 6 + 8 inches','35–40',33000],['6 + 9 + 11 inches','70–80',60000]];
 return `<div class="wrap">${title('Sizes and starting prices','A guide to servings and where prices start.')}<div class="narrow sizes-guide"><p>Every cake is finished with Swiss meringue buttercream. These are the starting prices for each size, the same for every flavour. The chef chooses the sizes each cake comes in and sets its price, shown on the cake’s page. The decoration in a cake’s photo is included in its price.</p><table class="size-table"><caption>Single-tier cakes</caption><thead><tr><th scope="col">Size</th><th scope="col">Diameter</th><th scope="col">Servings</th><th scope="col">Weight</th><th scope="col">From</th></tr></thead><tbody>${rows.map(([s,d,v,w,p])=>`<tr><th scope="row">${s}</th><td>${d}</td><td>${v}</td><td>${w}</td><td>${money(p)}</td></tr>`).join('')}</tbody></table><table class="size-table"><caption>Tiered cakes</caption><thead><tr><th scope="col">Tiers</th><th scope="col">Servings</th><th scope="col">From</th></tr></thead><tbody>${tiers.map(([t,v,p])=>`<tr><th scope="row">${t}</th><td>${v}</td><td>${money(p)}</td></tr>`).join('')}</tbody></table><p class="small">Larger sizes are available by request. Some decoration details cost extra; the chef agrees the price with you before you pay.</p><div class="form-actions"><a class="button primary" href="shop.html">Shop cakes →</a><a class="button" href="custom.html">Create your own →</a></div></div></div>`}
// Reorder from history: today's price, allergens, stock and dates are checked again; nothing is cloned.
function reorder(){const d=pastOrderDate();const lines=[
 {id:'pink',was:'Vanilla Raspberry · S · 6 inches · 7–10 servings',paid:9000,add:true,changes:[['same','Same price: £90.'],['changed','The chef updated the photo after your order (version 2 → 3). Your past order keeps the photo you agreed.']]},
 {id:'chocolate',was:'Snickers · S · 6 inches · 7–10 servings · made to order',paid:9000,add:true,changes:[['changed','Now sold ready-made: 1 left (example).'],['same','Same price: £90.'],['allergen','Contains PEANUTS. Please check again before ordering.']]},
 {id:'raspberry',was:'Chocolate Raspberry · M · 7 inches · 12–14 servings',paid:10500,add:false,changes:[['bad','Not available to order right now, so it can’t be added.']]}];
 const now=lines.filter(l=>l.add).reduce((n,l)=>n+product(l.id).price,0);
 const tag={same:'<span class="change-tag">Same</span>',changed:'<span class="change-tag">Changed</span>',allergen:'<span class="change-tag bad">Allergen</span>',bad:'<span class="change-tag bad">Unavailable</span>'};
 return `<div class="wrap">${title('Order again','DEMO-014 · '+escape(dateLabel(d))+' · example order')}<div class="narrow reorder"><div class="notice"><p>We’ve checked your old order against today’s cakes. Here’s what changed. Nothing is in your bag until you choose.</p></div>${lines.map(l=>{const p=product(l.id);return `<article class="reorder-line">${image(l.id)}<div><h2>${p.name}</h2><p class="small quiet">You ordered: ${l.was} · ${money(l.paid)}</p><ul>${l.changes.map(([k,t])=>`<li>${tag[k]} ${t}</li>`).join('')}</ul>${l.add?'':`<a class="text-link" href="custom.html?ref=${l.id}&amp;rev=${p.rev}">Request changes to this design →</a>`}</div><p class="reorder-price">${l.add?money(p.price):'—'}</p></article>`}).join('')}<div class="reorder-total"><p>Your old order: <strong>${money(28500)}</strong> for 3 cakes.</p><p>Today: <strong>${money(now)}</strong> for 2 cakes, checked again at checkout.</p></div><p class="small">Not copied from your old order: your date and time, any discount code, and photo permissions. You’ll choose a new date, and anything else is asked again. If a price had changed, you’d see the old and new price here first.</p><div class="form-actions"><button class="primary" type="button" id="reorder-add">Add 2 cakes to bag ${icon('arrow')}</button><a class="button" href="account.html">Back to your account</a></div><p class="small quiet">Example order for design review. Order history needs sign-in (next sketch).</p></div></div>`}
function bindAccount(){const f=document.querySelector('#signin-preview'),st=document.querySelector('#signin-status');f?.addEventListener('submit',e=>{e.preventDefault();st.textContent='Preview: in the live site we’d email a sign-in link to this address (the first link creates your account). Nothing was sent.'});document.querySelector('#google-preview')?.addEventListener('click',()=>{st.textContent='Preview: in the live site this opens Google sign-in. Nothing was opened.'})}
function bindFavourites(){const panel=document.querySelector('#merge-panel');if(!panel)return;const done=msg=>{panel.innerHTML=`<p>${msg}</p>`;panel.setAttribute('role','status');panel.tabIndex=-1;panel.focus()};document.querySelector('#merge-yes').addEventListener('click',()=>done('Added to your account (example). They’re still on this device too. Nothing was sent in this preview.'));document.querySelector('#merge-no').addEventListener('click',()=>done('Kept on this device only. You can add them to your account later.'))}
function bindReorder(){document.querySelector('#reorder-add')?.addEventListener('click',()=>{const ids=bag();for(const id of ['pink','chocolate'])if(!ids.includes(id))ids.push(id);if(write('bag',ids)){write('date','');write('slot','');location.href='bag.html'}})}
function bindCakeSize(){document.querySelectorAll('[name=size]').forEach(r=>r.addEventListener('change',()=>{const u=new URL(location.href);u.searchParams.set('id',r.value);location.replace(u.toString())}))}
function bindReviewBar(){document.querySelector('#demo-state')?.addEventListener('change',e=>{const u=new URL(location.href);e.target.value?u.searchParams.set('demo',e.target.value):u.searchParams.delete('demo');location.href=u.toString()})}
// Gallery problem states (K01 / C-GALLERY): fetch failed with Try again, and an empty catalogue.
function bindGalleryStates(){if(!['gallery-error','gallery-empty'].includes(DEMO))return;const grid=document.querySelector('#product-grid'),count=document.querySelector('#result-count'),selects=document.querySelectorAll('.shop-controls select');document.querySelector('#no-results').hidden=true;selects.forEach(x=>x.disabled=true);
 if(DEMO==='gallery-empty'){grid.innerHTML='';grid.insertAdjacentHTML('afterend','<div class="empty gallery-state" id="gallery-state"><h2>No cakes to show right now</h2><p>The chef is updating the collection. You can still tell us about the cake you’d like.</p><div class="form-actions centred"><a class="button primary" href="custom.html">Create your own →</a><a class="button" href="contact.html">Contact the chef</a></div></div>');count.textContent='No cakes to show right now.';return}
 grid.innerHTML='';grid.insertAdjacentHTML('afterend','<div class="empty gallery-state" id="gallery-state"><h2>We couldn’t load the cakes</h2><p>Please check your connection and try again. Nothing you saved has been lost.</p><button type="button" class="primary" id="gallery-retry">Try again</button></div>');count.textContent='We couldn’t load the cakes.';
 document.querySelector('#gallery-retry').addEventListener('click',async e=>{const box=document.querySelector('#gallery-state');e.currentTarget.disabled=true;e.currentTarget.textContent='Loading cakes…';count.textContent='Loading cakes…';grid.setAttribute('aria-busy','true');await wait(450);grid.removeAttribute('aria-busy');box.remove();selects.forEach(x=>x.disabled=false);document.querySelector('#sort').dispatchEvent(new Event('change'));const first=grid.querySelector('a');if(first)first.focus()})}
function render(){const pages={index:home,shop,cake:detail,custom,bag:bagPage,checkout,order:orderPage,account,favourites,sizes,reorder};document.querySelector('#app').innerHTML=header()+`<main id="main">${(pages[PAGE]||information)()}</main>`+footer()+dateDialog()+'<div id="toast" class="toast" role="status"></div>';bindReviewBar();bindGlobal();bindCalendars();bindPicker();if(PAGE==='shop'){bindShop();bindGalleryStates()}if(PAGE==='custom')bindCustom();if(PAGE==='checkout')bindCheckout();if(PAGE==='order')bindOrder();if(PAGE==='account')bindAccount();if(PAGE==='favourites')bindFavourites();if(PAGE==='reorder')bindReorder();if(PAGE==='cake')bindCakeSize();}
function information(){if(PAGE==='about')return `<div class="wrap">${title('Made to celebrate','GK Cake London · St Katharine Docks')}<section class="home-story" style="padding-top:0"><div class="story-copy"><h2>Your vision. Our craft.</h2><p>From soft, romantic piping to sculptural silver details, our gallery is a place to find the cake that feels like your occasion.</p><p>Choose an approved cake example or work with Elina on a bespoke design. We agree your flavour, servings, decoration and date together.</p><a class="button primary" href="custom.html">Tell us your idea →</a></div><div class="story-photo">${image('garden')}</div></section></div>${banner()}`;
if(PAGE==='contact')return `<div class="wrap">${title('Let’s talk cake','Something in mind? We’d love to hear it.')}<div class="narrow"><h2>Tell us about your celebration</h2><p>For a custom design, start with your date, servings, flavour and ideas.</p><a class="button primary" href="custom.html">Create your own →</a><div class="content-banner"></div><h2>Contact details</h2><p>Instagram: <strong>@gk.cake.london</strong><br>Email: <strong>gk.cake.london@gmail.com</strong></p><p>Collection: St Katharine Docks, London. The exact address and instructions are shared privately.</p><p class="small quiet">This POC displays contact details without opening or sending a message.</p></div></div>`;
if(PAGE==='faq')return `<div class="wrap">${title('A few useful details','Before the celebration begins.')}<div class="narrow">${[['How far ahead should I order?','Ordinary cakes need at least 192 hours from successful full payment to handover. The chef may approve a shorter lead for a specific ready-made or resale cake. That is an individual agreement, not a general same-day promise.'],['Where do I collect my cake?','Collection is from St Katharine Docks. Thursday 11:00–17:00, Friday 10:00–17:00, Saturday 12:30–15:00 and Sunday 11:00–12:00. Available 60-minute slots are shown during ordering. The full address is sent privately.'],['Do you deliver?','Collection is free. You can arrange and pay your own courier. GK delivery is assessed and quoted individually from £100, agreed with the chef, then paid separately through the website. There are no automatic delivery zones or tariffs.'],['Can I change the decoration or size?','Yes—request a custom version and agree the changes and final price with the chef before payment. Each listing’s price includes the decoration shown.'],['Where can I find allergen information?',NOTICE+' Check each cake’s individual contains declaration before purchase.'],['Can I change my collection time?','An available same-day time can be changed at least 6 hours before your current slot starts. For date changes, exceptions or no suitable slot, contact the chef directly.'],['What happens if a payment result is unclear?','Wait for the confirmed result; do not pay again. A payment started in the valid 24-hour window may finish later. If known payment success leaves insufficient preparation time, the chef must confirm feasibility and you must explicitly agree; otherwise a full refund is due.']].map(([q,a],i)=>`<details class="accordion" ${i===0?'open':''} ${i===1?'id="collection"':''}><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></div>`;
return `<div class="wrap">${title('Policy preview','Design content for review, not final published Terms.')}<div class="narrow"><h2>Cancellation & refunds</h2><p>The current business policy uses the original handover time: customer cancellation strictly more than 120 hours before it returns 100% of the amount actually paid; at that boundary or later, 50%. Chef cancellation returns 100%. Moving the date or time does not reset that original deadline. Separately paid GK delivery is accounted for in the overall entitlement and refunded separately by the chef.</p><p>Nothing in this cancellation and refund policy affects the customer’s statutory rights where a product is faulty, not as described or otherwise does not meet applicable legal requirements.</p><h2>Your information</h2><p>This POC has no analytics or account service. Demo cake IDs, date, time, handover choice, discount code and order state are kept in this tab’s session storage. Favourites are kept on this device for a year, and a custom-request draft (without photos) for 30 days, in this browser’s local storage. Photos you add stay on the current page and are never uploaded. Nothing is sent.</p><button id="clear-demo">Clear demo data on this device</button><h2 id="prototype">About this prototype</h2><p>GK-016 · discovery, cake page, custom request and shared date-and-time picker r01c (Creator-approved 2026-11-05), built on GK-017 r01 (checkout) and the approved GK-015 r12 visual foundation. Dates are worked out from today’s date in London. All transactions and availability are simulated. The hero is a GPT Image 2 extraction of the Creator’s selected reference with its grey studio background removed on-device (subject mask only, original pixels unchanged), so the page shows through it; it is not a product photograph or a newly approved cake specification. The cake photos are approved processed owner photographs. Three product configurations are approved examples; additional designs are inspiration only. The decorative chrome logos use the Creator-selected composite.png. The header wordmark follows the selected website reference. Motion (page transitions, reveals, ticker, rotating badge, pointer effects) respects the reduced-motion setting.</p><p>Final supplier/label, legal, payment-method and operational verification remain separate project work. This is not a live shop.</p></div></div>`}
let toastTimer;
function toast(message){const el=document.querySelector('#toast');if(!el)return;el.textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.textContent='',4000)}
function bindGlobal(){document.querySelector('.menu-toggle').addEventListener('click',e=>{const b=e.currentTarget;const open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(open));b.setAttribute('aria-label',open?'Close menu':'Open menu');document.querySelector('#mobile-menu').classList.toggle('open',open)});
document.querySelectorAll('[data-save]').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.save;const ids=saved();const next=ids.includes(id)?ids.filter(v=>v!==id):[...ids,id];if(setSaved(next)){button.setAttribute('aria-pressed',String(next.includes(id)));button.setAttribute('aria-label',`${next.includes(id)?'Unsave':'Save'} ${product(id).name}`);toast(next.includes(id)?'Saved on this device for a year.':'Removed from favourites.');if(PAGE==='favourites')renderAfterRemoval('[data-save]',button)}}));
document.querySelectorAll('[data-remove]').forEach(b=>b.addEventListener('click',()=>{if(write('bag',bag().filter(id=>id!==b.dataset.remove)))renderAfterRemoval('[data-remove]',b)}));
document.querySelector('#add-bag')?.addEventListener('click',e=>{const id=e.currentTarget.dataset.product;if(!chosenDate())return;const ids=bag();if(!ids.includes(id))ids.push(id);if(write('bag',ids))location.href='bag.html'});
document.querySelector('#clear-demo')?.addEventListener('click',()=>{for(const key of ['bag','date','slot','order','code','mode','full-days','taken-done','too-soon','soon-done','empty-date','demo-owner']){try{sessionStorage.removeItem(STORE+key)}catch{}}removeDevice('favourites');removeDevice('draft');toast('Demo data cleared from this device.');});
}

function renderAfterRemoval(selector,button){const index=Array.from(document.querySelectorAll(selector)).indexOf(button);render();const remaining=document.querySelectorAll(selector);const target=remaining[Math.min(index,remaining.length-1)]||document.querySelector('main h1');if(target){if(target.tagName==='H1')target.tabIndex=-1;target.focus()}}
function bindShop(){const mode=document.querySelector('#filter-mode'),flavour=document.querySelector('#filter-flavour'),colour=document.querySelector('#filter-colour'),sort=document.querySelector('#sort');if(['orderable','inspiration','unavailable'].includes(params.get('mode')))mode.value=params.get('mode');function update(){let result=PRODUCTS.filter(p=>(mode.value==='all'||mode.value==='orderable'&&p.price&&p.mode!=='Unavailable'||mode.value==='inspiration'&&!p.price||mode.value==='unavailable'&&p.mode==='Unavailable')&&(flavour.value==='all'||p.flavour===flavour.value)&&(colour.value==='all'||p.colour===colour.value));if(sort.value==='price')result.sort((a,b)=>(a.price??Infinity)-(b.price??Infinity));if(sort.value==='name')result.sort((a,b)=>a.name.localeCompare(b.name));document.querySelector('#product-grid').innerHTML=result.map(card).join('');document.querySelector('#result-count').textContent=`${result.length} cakes shown`;document.querySelector('#no-results').hidden=result.length>0;document.querySelectorAll('#product-grid [data-save]').forEach(b=>b.addEventListener('click',()=>{const ids=saved(),id=b.dataset.save;const next=ids.includes(id)?ids.filter(v=>v!==id):[...ids,id];if(setSaved(next)){b.setAttribute('aria-pressed',String(next.includes(id)));b.setAttribute('aria-label',`${next.includes(id)?'Unsave':'Save'} ${product(id).name}`);toast(next.includes(id)?'Saved on this device for a year.':'Removed from favourites.')}}));}[mode,flavour,colour,sort].forEach(el=>el.addEventListener('change',update));document.querySelector('#clear-filters').addEventListener('click',()=>{mode.value=flavour.value=colour.value='all';sort.value='featured';update()});update();}
function bindCheckout(){const form=document.querySelector('#checkout-form');if(!form)return;const items=bag().map(product),sub=items.reduce((n,p)=>n+p.price,0);const $=id=>document.querySelector('#'+id);const slotValue=()=>form.querySelector('input[name=slot]:checked')?.value||'';let failOnce=DEMO==='times-error';let revision=0,loading=false,submitting=false,applied=['DEMO10','FREEDELIVERY'].includes(read('code',''))?read('code',''):'';
const london=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});
function handover(date,slot){if(!date||!slot)return null;const [y,mo,d]=date.split('-').map(Number),[h,m]=slot.split('–')[0].split(':').map(Number);for(const off of [0,60,-60]){const t=Date.UTC(y,mo-1,d,h,m)-off*60000;const parts=Object.fromEntries(london.formatToParts(new Date(t)).map(x=>[x.type,x.value]));if(+parts.year===y&&+parts.month===mo&&+parts.day===d&&+parts.hour===h&&+parts.minute===m)return t}return null}
function deadlineLabel(t){const d=new Date(t);const time=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(d);const day=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',weekday:'short',day:'numeric',month:'long'}).format(d);return `${time} (London time) on ${day}`}
const mode=()=>form.elements.fulfilment.value;
function totals(){const discount=applied==='DEMO10'?Math.floor((sub*1000+5000)/10000):0;return{discount,total:sub-discount}}
function showChip(){const on=!!applied;$('code-row').hidden=on;$('code-applied').hidden=!on;$('remove-code').setAttribute('aria-label',on?'Remove code '+applied:'Remove code');$('code-chip-text').innerHTML=on?`<strong>${applied}</strong> ${applied==='DEMO10'?'· 10% off cakes · example code':'· free GK delivery, pending chef review · example code'}`:''}
function setStatus(html,kind=''){const st=$('code-status');st.className='small code-status '+kind;st.innerHTML=html;form.elements.code.setAttribute('aria-invalid',kind==='error'?'true':'false')}
function update(){const m=mode(),slot=loading?'':slotValue(),{discount,total}=totals(),delivery=m==='delivery';
$('sum-time').textContent=slot?(delivery?slot+' · requested, to be confirmed':slot+' · London time'):(delivery?'Requested time, to be confirmed':'Choose a time');
$('sum-mode').textContent={collection:'Collect · St Katharine Docks',courier:'Your courier collects',delivery:'GK delivery · chef confirms after payment'}[m];
$('sum-fulfil-label').textContent={collection:'Collection',courier:'Your courier',delivery:'GK delivery'}[m];$('sum-fulfil').textContent={collection:'Free',courier:'Arranged by you',delivery:applied==='FREEDELIVERY'?'Free if approved · after chef review':'Quoted after payment · paid separately'}[m];
$('sum-discount-row').hidden=!discount;$('sum-discount-label').textContent='Discount · DEMO10 (10%)';$('sum-discount').textContent='−'+money(discount);
$('sum-total-label').textContent=delivery?'To pay now · cakes':'To pay now';$('sum-total').textContent=money(total);
$('sum-total-top-label').textContent=delivery?'To pay now · cakes':'To pay now';$('sum-total-top').textContent=money(total);
const pay=$('preview-payment');if(!submitting){pay.disabled=loading;$('pay-label').textContent=loading?'Loading available times…':(delivery?'Pay for cakes · ':'Continue to secure payment · ')+money(total)}
$('assure-hold').hidden=false;$('assure-twice').hidden=false;$('assure-confirm').textContent=delivery?'Your cake order is confirmed when we receive the payment. The chef then confirms your delivery time and emails the delivery quote.':'Your order is confirmed only when we receive the payment. We’ll email you.';
$('sum-note').textContent=delivery?(applied==='FREEDELIVERY'?'In pounds (GBP). Delivery is free if the chef approves your code, otherwise quoted and paid separately after payment.':'In pounds (GBP). Delivery is quoted by the chef (from £100) and paid separately after payment.'):'In pounds (GBP). Decoration shown is included.';
const terms=$('refund-terms');
const t=handover(chosenDate(),slot);if(!t){terms.innerHTML='<p class="co-label">Cancellation and refunds</p><p>Choose a time to see your exact cancellation deadline.</p>';return}
terms.innerHTML=delivery?`<p class="co-label">Cancellation and refunds</p><p>Cancel before <strong>${escape(deadlineLabel(t-120*3600000))}</strong> for a full refund of everything you’ve paid: <strong>${money(total)}</strong> for the cakes, plus delivery if you’ve paid it.</p><p>From then on, or if nobody receives the cake, you get <strong>50%</strong> of everything you’ve paid, including delivery. If we have to cancel, you get 100% back.</p><p>This deadline is set from the delivery time you request now. It doesn’t move if the chef confirms a different time, or if you later change the date or time. If we can’t deliver to your address, the chef will contact you about your options.</p>`:`<p class="co-label">Cancellation and refunds</p><p>Cancel before <strong>${escape(deadlineLabel(t-120*3600000))}</strong> for a full refund of <strong>${money(total)}</strong>.</p><p>From then on, or ${m==='courier'?'if your courier doesn’t collect it':'if the cake isn’t collected'}, you get <strong>50% (${money(Math.ceil(total/2))})</strong>. If we have to cancel, you get 100% back.</p><p>Once you’ve paid, moving your date or time won’t change this deadline. After handover, contact the chef to request your 50% refund or if something is wrong.</p>`}
let preferSlot='';
async function refreshSlots(){const current=++revision,delivery=mode()==='delivery',prev=preferSlot||slotValue()||read('slot','');preferSlot='';if(applied==='FREEDELIVERY'&&!delivery){applied='';write('code','');showChip();setStatus('FREEDELIVERY removed: it only works with GK delivery.')}$('delivery-note').hidden=!delivery;$('address-field').hidden=!delivery;if(!delivery)clearError('address');$('checkout-slot-label').textContent=delivery?'Requested delivery time · subject to chef confirmation':'Collection time · London time';loading=true;const list=$('slot-list'),extra=$('slot-extra');extra.innerHTML='';list.innerHTML='<span class="slot-skeleton" aria-hidden="true"></span>'.repeat(3);$('slot').setAttribute('aria-busy','true');$('slot-status').textContent='Loading available times…';update();await wait(DEMO==='times-slow'?3500:450);if(current!==revision)return;$('slot').removeAttribute('aria-busy');loading=false;
if(failOnce){failOnce=false;list.innerHTML='';$('slot-status').textContent='We couldn’t load the times. Your details are kept.';extra.innerHTML='<button type="button" id="slot-retry">Try again</button>';$('slot-retry').addEventListener('click',()=>refreshSlots());update();return}
if(DEMO==='times-empty'&&!read('empty-date',''))write('empty-date',chosenDate());
const res=DEMO==='times-empty'&&read('empty-date','')===chosenDate()?{slots:[]}:scheduleFor(chosenDate(),mode(),'purchase',placesNeeded(),{until:readyUntil()});
if(!res.slots.length){list.innerHTML='';$('slot-status').textContent=res.reason==='ready_expiry'?`${shortDate(chosenDate())} is after your ready-made cake’s collect-by date (${shortDate(READY_UNTIL)}). Choose an earlier date, or contact the chef.`:`No times left on ${shortDate(chosenDate())} for this option. Choose another date, or contact the chef.`;extra.innerHTML='<div class="slot-empty"><button type="button" id="slot-change-date">Change date</button><a class="text-link" href="contact.html">Contact the chef →</a></div>';$('slot-change-date').addEventListener('click',()=>document.querySelector('[data-date]').click());update();return}
const labels=res.slots.map(s=>s.label);list.innerHTML=res.slots.map(s=>`<label class="slot-option"><input type="radio" name="slot" value="${s.label}" data-slot-id="${s.id}" ${s.label===prev?'checked':''}><span><strong>${s.label}</strong><small>${delivery?'Requested, the chef confirms':'Available'}</small></span></label>`).join('');$('slot-status').textContent=prev&&labels.includes(prev)?`Your time ${prev} is still available${delivery?' to request':''}.`:prev?`${prev} isn’t available for this option. Choose another time.`:`${labels.length} times available.`;update()}
form.querySelectorAll('[name=fulfilment]').forEach(r=>r.addEventListener('change',()=>{write('mode',mode());refreshSlots()}));$('slot').addEventListener('change',e=>{if(e.target.name!=='slot')return;clearError('slot');$('slot-status').textContent='';update()});
// The shared picker updates checkout in place, so name, email, address, code and ticks are all kept.
document.addEventListener('gk:when-changed',e=>{const {date,slot,mode:m}=e.detail;form.querySelector('.co-date strong').textContent=dateLabel(date);const dd=form.parentElement.querySelector('.sum-meta dd');if(dd)dd.textContent=dateLabel(date);if(m&&m!==mode()){form.querySelector(`[name=fulfilment][value="${m}"]`).checked=true;write('mode',m)}preferSlot=slot;refreshSlots()});
$('other-payer').addEventListener('change',e=>{$('payer-field').hidden=!e.target.checked;if(!e.target.checked){form.elements.payer.value='';clearError('payer')}});
function showError(id){const el=document.getElementById(id);el?.setAttribute('aria-invalid','true');const msg=document.getElementById(id+'-error');if(msg)msg.hidden=false;if(el){const d=(el.getAttribute('aria-describedby')||'').split(' ').filter(Boolean);if(!d.includes(id+'-error'))el.setAttribute('aria-describedby',[...d,id+'-error'].join(' '))}}
function clearError(id){const el=document.getElementById(id);el?.removeAttribute('aria-invalid');const msg=document.getElementById(id+'-error');if(msg)msg.hidden=true;if(el){const d=(el.getAttribute('aria-describedby')||'').split(' ').filter(x=>x&&x!==id+'-error');d.length?el.setAttribute('aria-describedby',d.join(' ')):el.removeAttribute('aria-describedby')}}
['name','email','payer','address'].forEach(id=>document.getElementById(id).addEventListener('input',()=>clearError(id)));$('reviewed').addEventListener('change',()=>clearError('reviewed'));
$('apply-code').addEventListener('click',()=>{const code=form.elements.code.value.trim().toUpperCase();if(!code){setStatus('Enter a code, or continue without one.','error');form.elements.code.focus();return}if(applied){setStatus(`Only one code per order. Remove <strong>${applied}</strong> first.`,'error');return}if(code==='DEMO10'){applied='DEMO10';write('code',applied);form.elements.code.value='';showChip();update();setStatus(`DEMO10 applied: 10% off cakes. New total ${money(totals().total)}.`,'success');$('code-chip-text').focus();return}if(code==='FREEDELIVERY'){if(mode()!=='delivery'){setStatus(mode()==='courier'?'FREEDELIVERY is for GK delivery only. It never covers your own courier.':'FREEDELIVERY is for GK delivery. Choose GK delivery to use it.','error');return}applied='FREEDELIVERY';write('code',applied);form.elements.code.value='';showChip();update();setStatus('FREEDELIVERY saved. Delivery is free if the chef confirms your address is within this code’s distance limit.','success');$('code-chip-text').focus();return}setStatus('We don’t recognise that code. Check the spelling, or continue without one.','error')});
form.elements.code.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$('apply-code').click()}});
$('remove-code').addEventListener('click',()=>{const was=applied;applied='';write('code','');showChip();update();setStatus(`${was} removed. New total ${money(totals().total)}. One code per order.`);form.elements.code.focus()});
form.addEventListener('submit',e=>{e.preventDefault();if(submitting)return;if(!chosenDate()){toast('Choose a demo date and time first.');document.querySelector('[data-date]').click();return}if(loading){$('slot-status').textContent='Times are still loading. Please wait a moment.';return}
const errs=[];const v=n=>form.elements[n].value.trim();if(!slotValue()){showError('slot');errs.push(['slot','Choose a time'])}if(!v('name')){showError('name');errs.push(['name','Enter your full name'])}if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v('email'))){showError('email');errs.push(['email','Enter an email address like name@example.com'])}if(mode()==='delivery'&&v('address').length<6){showError('address');errs.push(['address','Enter the delivery address, including the postcode'])}if(form.elements.otherPayer.checked&&!v('payer')){showError('payer');errs.push(['payer','Enter the payer’s full name'])}if(!form.elements.reviewed.checked){showError('reviewed');errs.push(['reviewed','Tick to confirm you’ve checked your order'])}
const box=$('error-summary');if(errs.length){box.hidden=false;box.innerHTML=`<p><strong>Please check ${errs.length===1?'1 thing':errs.length+' things'} before paying</strong></p><ul>${errs.map(([id,t])=>`<li><a href="#${id}">${t}</a></li>`).join('')}</ul>`;box.focus();return}box.hidden=true;
submitting=true;const pay=$('preview-payment');pay.setAttribute('aria-disabled','true');pay.setAttribute('aria-busy','true');pay.classList.add('is-busy');$('pay-label').textContent='Opening secure payment…';$('pay-status').textContent='Opening secure payment…';const {discount,total}=totals();const data={items:bag(),date:chosenDate(),slot:slotValue(),mode:mode(),state:form.elements.outcome.value,code:applied||null,discount,total};setTimeout(()=>{if(write('order',data)){if(data.state==='success'){write('bag',[]);write('code','');write('mode','')}location.href='order.html'}},700)});
$('error-summary').addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(!a)return;e.preventDefault();document.getElementById(a.getAttribute('href').slice(1))?.focus()});
const savedMode=read('mode','');if(['courier','delivery'].includes(savedMode))form.querySelector(`[name=fulfilment][value=${savedMode}]`).checked=true;if(applied==='FREEDELIVERY'&&mode()!=='delivery'){applied='';write('code','');showChip();setStatus('FREEDELIVERY removed: it only works with GK delivery.')}else{showChip();if(applied)setStatus(`<strong>${applied}</strong> is still applied.`,'success')}update();refreshSlots()}

function bindOrder(){document.querySelector('#change-time')?.addEventListener('click',()=>{const p=document.querySelector('#order-action');p.hidden=false;p.textContent='Demo: choose another available slot on the same day at least 6 hours before the current slot starts. Date changes and exceptions need chef agreement. No appointment was changed.'});document.querySelector('#cancel-preview')?.addEventListener('click',()=>{const p=document.querySelector('#order-action');const o=params.get('example')==='true'?{items:['pink']}:read('order',{items:[]});const total=Number.isInteger(o.total)?o.total:o.items.map(product).filter(Boolean).reduce((n,v)=>n+v.price,0);p.hidden=false;p.textContent=`Cancellation preview: ${money(total)} strictly more than 120 hours before the original handover; ${money(Math.ceil(total/2))} at that boundary or later. Chef cancellation: ${money(total)}. These examples have no delivery payment. No cancellation submitted or refund processed.`});}
render();
// r10: pointer spotlight on cake tiles and a gentle magnetic pull on primary buttons; fine pointers with motion allowed only.
if(matchMedia('(pointer:fine)').matches&&!matchMedia('(prefers-reduced-motion: reduce)').matches){document.addEventListener('pointermove',e=>{const t=e.target instanceof Element?e.target:null;if(!t)return;const tile=t.closest('.product-photo,.detail-visual');if(tile){const r=tile.getBoundingClientRect();tile.style.setProperty('--mx',`${((e.clientX-r.left)/r.width*100).toFixed(1)}%`);tile.style.setProperty('--my',`${((e.clientY-r.top)/r.height*100).toFixed(1)}%`)}const b=t.closest('.button.primary,button.primary');if(b&&!b.disabled){const r=b.getBoundingClientRect();b.style.setProperty('--tx',`${((e.clientX-r.left-r.width/2)*.1).toFixed(1)}px`);b.style.setProperty('--ty',`${((e.clientY-r.top-r.height/2)*.18).toFixed(1)}px`)}},{passive:true});document.addEventListener('pointerout',e=>{const b=e.target instanceof Element?e.target.closest('.button.primary,button.primary'):null;if(b&&!b.contains(e.relatedTarget)){b.style.removeProperty('--tx');b.style.removeProperty('--ty')}},{passive:true})}

// r12: while the Shop filter bar is stuck, one frosted layer sits behind the header island and the bar
// (outside the bar's own glass, so it can blur what scrolls underneath) and fades out softly below it.
document.addEventListener('DOMContentLoaded',()=>{const update=()=>{const c=document.querySelector('.shop-controls');if(!c)return;let scrim=document.querySelector('.sticky-scrim');if(!scrim){scrim=document.createElement('div');scrim.className='sticky-scrim';scrim.setAttribute('aria-hidden','true');document.body.appendChild(scrim)}const s=getComputedStyle(c);if(s.position!=='sticky'){scrim.classList.remove('on');return}const top=parseFloat(s.top)||0;scrim.style.setProperty('--scrim-h',Math.round(top+c.offsetHeight+28)+'px');scrim.classList.toggle('on',c.getBoundingClientRect().top<=top+.5)};addEventListener('scroll',update,{passive:true});addEventListener('resize',update);update()});
